window.STUDY_OS_DATA = {"questions":[{"id":"shobo6-0001","資格":"消防設備士乙6類","分野":"機械に関する基礎的知識","難易度":"標準","頻出度":4,"販売対象":true,"根拠":"参考書 第1章 Lesson1「力について(1)」確認テストページより作成","問題":"力の大きさ、方向、作用点の3つをまとめて何と呼ぶか。","選択肢A":"力の3要素","選択肢B":"力のモーメント","選択肢C":"力のつり合い","選択肢D":"力の合成","正解":"A","解説":"力は大きさ・方向・作用点の3つの要素によって表され、これを力の3要素と呼ぶ。力を矢印で表す際、矢印の向きが方向、矢印の長さが大きさ、矢印の始点が作用点に対応する。","間違えやすい理由":"力のモーメント（回転力）と混同しやすいが、モーメントは力の3要素とは別の概念で、力が回転軸を回転させようとする働きを表す。","音声用文章":"力は、大きさ、方向、作用点の3つの要素で表されます。これを力の3要素と言います。","公式分野":"機械に関する基礎的知識","詳細タグ":["力学","力の3要素"],"学習タグ":["頻出"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0002","資格":"消防設備士乙6類","分野":"機械に関する基礎的知識","難易度":"標準","頻出度":3,"販売対象":true,"根拠":"参考書 第1章 Lesson1「力について(1)」確認テストページより作成","問題":"同一直線上にない2つの力を合成するとき、合力の作図方法として正しいものはどれか。","選択肢A":"2力を2辺とする平行四辺形の対角線として作図する","選択肢B":"2力の大きさを単純に足し合わせる","選択肢C":"2力の大きさの差を求める","選択肢D":"2力の作用点を結ぶ直線を引く","正解":"A","解説":"同一直線上にない2力を合成する場合、2力を2辺とする平行四辺形を作図し、その対角線が合力の大きさと方向を表す（平行四辺形の法則）。","間違えやすい理由":"2力が同一直線上かつ同じ向きの場合は単純な足し算（B）でよいが、方向が異なる場合は平行四辺形による作図が必要になる点を混同しやすい。","音声用文章":"同一直線上にない2つの力を合成するときは、2力を2辺とする平行四辺形を書いて、その対角線が合力になります。","公式分野":"機械に関する基礎的知識","詳細タグ":["力学","力の合成"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0003","資格":"消防設備士乙6類","分野":"機械に関する基礎的知識","難易度":"標準","頻出度":3,"販売対象":true,"根拠":"参考書 第1章 Lesson1「力について(1)」確認テストページより作成","問題":"3つ以上の力が1点でつり合う条件として正しいものはどれか。","選択肢A":"すべての力を合成した合力がゼロになる","選択肢B":"すべての力の大きさが等しい","選択肢C":"すべての力が同一直線上にある","選択肢D":"力の数が偶数である","正解":"A","解説":"複数の力がつり合っている状態とは、それらの力を合成した結果である合力の大きさがゼロになる状態を指す。力の大きさが等しい必要はなく、方向や作用点の関係によってつり合いが成立する。","間違えやすい理由":"「つり合う」という言葉から力の大きさが等しいことをイメージしやすいが、実際には合力がゼロになることが条件であり、大きさが異なる複数の力でもつり合いは成立する。","音声用文章":"複数の力がつり合っている状態とは、それらの力を合成した合力の大きさがゼロになっている状態のことです。","公式分野":"機械に関する基礎的知識","詳細タグ":["力学","力のつり合い"],"学習タグ":["間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0004","資格":"消防設備士乙6類","分野":"機械に関する基礎的知識","難易度":"標準","頻出度":5,"販売対象":true,"根拠":"参考書 第1章 Lesson2「力について(2)」確認テストページより作成","問題":"回転軸から3m離れた点に、軸に対して垂直な方向に200Nの力を加えたとき、力のモーメントの大きさとして正しいものはどれか。","選択肢A":"600N・m","選択肢B":"203N・m","選択肢C":"66.7N・m","選択肢D":"197N・m","正解":"A","解説":"力のモーメントMは、力Fと回転軸から作用点までの距離lの積で求められる（M=F×l）。この問題では200N×3m=600N・mとなる。","間違えやすい理由":"力のモーメントを求める公式M=F×lを、足し算（F+l）と勘違いしたり、単位をN・mではなくNやmだけで答えてしまう間違いが多い。","音声用文章":"力のモーメントは、力の大きさと、回転軸から作用点までの距離の積で求められます。式で表すと、M イコール エフ かける エル です。","公式分野":"機械に関する基礎的知識","詳細タグ":["力学","力のモーメント"],"学習タグ":["頻出","計算問題"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0005","資格":"消防設備士乙6類","分野":"機械に関する基礎的知識","難易度":"やや難","頻出度":3,"販売対象":true,"根拠":"参考書 第1章 Lesson2「力について(2)」確認テストページより作成","問題":"1点において、右回りと左回りの力のモーメントがつり合っている場合の関係として正しいものはどれか。","選択肢A":"右回りのモーメントの合計と左回りのモーメントの合計が等しい","選択肢B":"右回りの力の大きさと左回りの力の大きさが等しい","選択肢C":"右回りの腕の長さと左回りの腕の長さが等しい","選択肢D":"右回りと左回りの力の数が等しい","正解":"A","解説":"力のモーメントのつり合いでは、右回り（時計回り）のモーメントの合計と、左回り（反時計回り）のモーメントの合計が等しくなる。力の大きさや腕の長さそのものが等しい必要はない。","間違えやすい理由":"力そのものの大きさが等しいと考えがちだが、モーメントは力×距離で決まるため、力が小さくても腕（距離）が長ければ大きなモーメントになり、つり合いが成立する場合がある。","音声用文章":"力のモーメントがつり合っている状態とは、右回りのモーメントの合計と、左回りのモーメントの合計が等しくなっている状態のことです。","公式分野":"機械に関する基礎的知識","詳細タグ":["力学","力のモーメントのつり合い"],"学習タグ":["間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0006","資格":"消防設備士乙6類","分野":"機械に関する基礎的知識","難易度":"標準","頻出度":4,"販売対象":true,"根拠":"参考書 第1章 Lesson3「仕事と摩擦」確認テストページより作成","問題":"150Nの力を加えて物体を3m移動させたとき、この力がした仕事の大きさとして正しいものはどれか。","選択肢A":"450J","選択肢B":"153J","選択肢C":"50J","選択肢D":"450W","正解":"A","解説":"仕事は、力の大きさと、物体が力の方向に移動した距離の積で求められる。150N×3m=450Jとなる。単位はジュール（J）であり、ワット（W）ではない点に注意する。","間違えやすい理由":"仕事の単位ジュール（J）と、仕事率の単位ワット（W）を混同しやすい。仕事率は仕事を時間で割った値であり、単純な仕事の計算とは異なる。","音声用文章":"仕事は、力の大きさと、力の方向に物体が移動した距離の積で表されます。単位はジュールです。","公式分野":"機械に関する基礎的知識","詳細タグ":["仕事","計算問題"],"学習タグ":["頻出"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0007","資格":"消防設備士乙6類","分野":"機械に関する基礎的知識","難易度":"標準","頻出度":4,"販売対象":true,"根拠":"参考書 第1章 Lesson3「仕事と摩擦」確認テストページより作成","問題":"800Jの仕事を20秒かけて行った場合、仕事率として正しいものはどれか。","選択肢A":"40W","選択肢B":"820W","選択肢C":"16000W","選択肢D":"780W","正解":"A","解説":"仕事率は、仕事の大きさを、その仕事に要した時間で割ることで求められる。800J÷20秒=40Wとなる。","間違えやすい理由":"仕事率を求める際に、時間で割る計算を掛け算と間違えたり、仕事(J)と仕事率(W)の違いを理解せずそのまま800をそのまま答えとしてしまう間違いが多い。","音声用文章":"仕事率は、仕事の大きさを、かかった時間で割ることで求められます。単位はワットです。","公式分野":"機械に関する基礎的知識","詳細タグ":["仕事率","計算問題"],"学習タグ":["頻出","計算問題"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0008","資格":"消防設備士乙6類","分野":"機械に関する基礎的知識","難易度":"標準","頻出度":4,"販売対象":true,"根拠":"参考書 第1章 Lesson3「仕事と摩擦」確認テストページより作成","問題":"最大摩擦力の大きさを決める要素の組み合わせとして正しいものはどれか。","選択肢A":"摩擦係数と垂直抗力（物体の重量）","選択肢B":"物体の速度と移動距離","選択肢C":"接触面積の大きさと物体の色","選択肢D":"物体の温度と湿度","正解":"A","解説":"最大摩擦力は、摩擦係数と、接触面に垂直に働く力（垂直抗力、水平面では物体の重量に相当）の積で求められる。接触面積の大小は最大摩擦力の大きさに直接関係しない。","間違えやすい理由":"接触面積が大きいほど摩擦力も大きくなると考えがちだが、実際には接触面積の大小は最大摩擦力に直接影響しない。摩擦係数は接触面の材質や状態によって決まる。","音声用文章":"最大摩擦力は、摩擦係数と、物体の重量にあたる垂直抗力との積で求められます。接触面積の大きさは関係ありません。","公式分野":"機械に関する基礎的知識","詳細タグ":["摩擦力"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0009","資格":"消防設備士乙6類","分野":"機械に関する基礎的知識","難易度":"標準","頻出度":3,"販売対象":true,"根拠":"参考書 第1章 Lesson4「物体の運動」確認テストページより作成","問題":"分速600mを秒速に直すといくらになるか。","選択肢A":"10m/秒","選択肢B":"600m/秒","選択肢C":"60m/秒","選択肢D":"1m/秒","正解":"A","解説":"分速600mとは、1分間（60秒）に600m進む速さである。秒速に直すには600m÷60秒を計算し、10m/秒となる。","間違えやすい理由":"分速から秒速に変換する際、60をかけるべきか割るべきか迷いやすい。時間の単位が小さくなる（分→秒）ので、同じ距離でも1秒あたりの値は小さくなる、つまり60で割る点に注意する。","音声用文章":"分速600メートルを秒速に直すには、600を60で割ります。答えは秒速10メートルです。","公式分野":"機械に関する基礎的知識","詳細タグ":["速度","計算問題"],"学習タグ":["計算問題"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0010","資格":"消防設備士乙6類","分野":"機械に関する基礎的知識","難易度":"標準","頻出度":4,"販売対象":true,"根拠":"参考書 第1章 Lesson4「物体の運動」確認テストページより作成","問題":"物体を自由落下させた場合の運動として正しいものはどれか。","選択肢A":"重力による一定の加速度（約9.8m/秒²）で加速しながら落下する等加速度直線運動","選択肢B":"常に一定の速度で落下する等速直線運動","選択肢C":"落下の途中で速度が周期的に増減する運動","選択肢D":"質量が大きい物体ほど速く落下する運動","正解":"A","解説":"自由落下運動は、重力加速度g（約9.8m/秒²）で一定に加速し続ける等加速度直線運動である。真空中では物体の質量に関係なく、同じ加速度で落下する。","間違えやすい理由":"質量が大きいほど速く落下すると誤解しやすいが、空気抵抗を無視した自由落下では、質量に関係なくすべての物体が同じ加速度で落下する。","音声用文章":"自由落下運動は、重力加速度によって一定の割合で加速し続ける、等加速度直線運動です。","公式分野":"機械に関する基礎的知識","詳細タグ":["運動","自由落下"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0011","資格":"消防設備士乙6類","分野":"機械に関する基礎的知識","難易度":"標準","頻出度":3,"販売対象":true,"根拠":"参考書 第1章 Lesson4「物体の運動」確認テストページより作成","問題":"物体に外力が加わらない、または加わる力がつり合っている場合の運動として正しいものはどれか（運動の法則）。","選択肢A":"静止している物体は静止を続け、運動している物体は等速直線運動を続ける","選択肢B":"物体は必ず徐々に減速して静止する","選択肢C":"物体は必ず一定の加速度で加速し続ける","選択肢D":"物体の運動状態は常にランダムに変化する","正解":"A","解説":"運動の第一法則（慣性の法則）により、物体に外力が加わらない、またはつり合っている場合、静止している物体はそのまま静止を続け、運動している物体はそのまま等速直線運動を続ける。","間違えやすい理由":"現実には摩擦力などが働くため物体は自然に減速するが、これは摩擦という外力が働いているためであり、外力がない理想状態では等速直線運動が続く点を混同しやすい。","音声用文章":"外力が加わらない、またはつり合っている場合、静止している物体は静止を続け、運動している物体は等速直線運動を続けます。これを運動の法則、慣性の法則と言います。","公式分野":"機械に関する基礎的知識","詳細タグ":["運動の法則","慣性"],"学習タグ":["頻出"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0012","資格":"消防設備士乙6類","分野":"機械に関する基礎的知識","難易度":"標準","頻出度":5,"販売対象":true,"根拠":"参考書 第1章 Lesson5「圧力と液体・気体」確認テストページより作成","問題":"密閉された容器内の液体や気体の一部に圧力を加えたとき、その圧力の伝わり方として正しいものはどれか（パスカルの原理）。","選択肢A":"容器内のどの部分にも均等に、同じ大きさで伝わる","選択肢B":"圧力を加えた点に近いほど強く伝わる","選択肢C":"容器の底面にのみ伝わる","選択肢D":"圧力を加えた方向とは逆方向にのみ伝わる","正解":"A","解説":"パスカルの原理により、密閉された容器内の液体や気体の一部に加えた圧力は、容器内のどの部分にも均等に、同じ大きさで伝わる。この原理は油圧装置などに応用されている。","間違えやすい理由":"圧力を加えた点に近いほど強く伝わると考えがちだが、パスカルの原理では液体・気体内のどの部分にも均等な大きさで圧力が伝わる点がポイントである。","音声用文章":"パスカルの原理とは、密閉された容器内の液体や気体の一部に圧力を加えると、その圧力は容器内のどの部分にも均等に伝わるという原理です。","公式分野":"機械に関する基礎的知識","詳細タグ":["圧力","パスカルの原理"],"学習タグ":["頻出"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0013","資格":"消防設備士乙6類","分野":"機械に関する基礎的知識","難易度":"やや難","頻出度":4,"販売対象":true,"根拠":"参考書 第1章 Lesson5「圧力と液体・気体」確認テストページより作成","問題":"温度が一定のとき、気体の体積と圧力の関係として正しいものはどれか（ボイルの法則）。","選択肢A":"気体の体積は圧力に反比例する","選択肢B":"気体の体積は圧力に比例する","選択肢C":"気体の体積と圧力は無関係である","選択肢D":"気体の体積は圧力の2乗に比例する","正解":"A","解説":"ボイルの法則により、温度が一定のとき、気体の体積は圧力に反比例する。圧力を2倍にすると体積は2分の1になる。","間違えやすい理由":"シャルルの法則（体積は絶対温度に比例）と混同しやすい。ボイルの法則は圧力と体積の反比例関係、シャルルの法則は温度と体積の比例関係を示す点を区別する必要がある。","音声用文章":"ボイルの法則とは、温度が一定のとき、気体の体積は圧力に反比例するという法則です。","公式分野":"機械に関する基礎的知識","詳細タグ":["圧力","ボイルの法則"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0014","資格":"消防設備士乙6類","分野":"機械に関する基礎的知識","難易度":"やや難","頻出度":4,"販売対象":true,"根拠":"参考書 第1章 Lesson5「圧力と液体・気体」確認テストページより作成","問題":"圧力が一定のとき、気体の体積と絶対温度の関係として正しいものはどれか（シャルルの法則）。","選択肢A":"気体の体積は絶対温度に比例する","選択肢B":"気体の体積は絶対温度に反比例する","選択肢C":"気体の体積は絶対温度と無関係である","選択肢D":"気体の体積は絶対温度の2乗に反比例する","正解":"A","解説":"シャルルの法則により、圧力が一定のとき、気体の体積は絶対温度に比例する。絶対温度が2倍になれば、体積も2倍になる。","間違えやすい理由":"ボイルの法則（圧力と体積は反比例）と混同しやすい。シャルルの法則は温度と体積の比例関係を示すという違いを整理して覚える必要がある。","音声用文章":"シャルルの法則とは、圧力が一定のとき、気体の体積は絶対温度に比例するという法則です。","公式分野":"機械に関する基礎的知識","詳細タグ":["圧力","シャルルの法則"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0015","資格":"消防設備士乙6類","分野":"機械に関する基礎的知識","難易度":"標準","頻出度":4,"販売対象":true,"根拠":"参考書 第1章 Lesson5「圧力と液体・気体」確認テストページより作成","問題":"絶対圧、ゲージ圧、大気圧の関係を正しく表す式はどれか。","選択肢A":"絶対圧 = ゲージ圧 + 大気圧","選択肢B":"絶対圧 = ゲージ圧 - 大気圧","選択肢C":"絶対圧 = ゲージ圧 × 大気圧","選択肢D":"絶対圧とゲージ圧は常に同じ値である","正解":"A","解説":"ゲージ圧（相対圧力）とは、大気圧を基準（ゼロ）として測った圧力である。絶対圧は大気圧を含めた圧力であり、絶対圧＝ゲージ圧＋大気圧という関係が成り立つ。","間違えやすい理由":"圧力計が示す値（ゲージ圧）がそのまま絶対圧だと誤解しやすいが、一般的な圧力計は大気圧を基準としたゲージ圧を表示しており、絶対圧を求めるには大気圧を加算する必要がある。","音声用文章":"絶対圧は、ゲージ圧に大気圧を加えた値です。ゲージ圧は、大気圧を基準にゼロとして測った圧力のことです。","公式分野":"機械に関する基礎的知識","詳細タグ":["圧力","ゲージ圧","絶対圧"],"学習タグ":["頻出"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0016","資格":"消防設備士乙6類","分野":"機械に関する基礎的知識","難易度":"標準","頻出度":3,"販売対象":true,"根拠":"参考書 第1章 Lesson7「機械材料(2)」確認テストページより作成","問題":"「展性」の説明として正しいものはどれか。","選択肢A":"打ち延ばして薄い板のように広げることができる性質","選択肢B":"引き伸ばして線状にできる性質","選択肢C":"外力を取り除くと元の形に戻る性質","選択肢D":"腐食しにくい性質","正解":"A","解説":"展性とは、金属をたたいたり圧延したりして、薄い板のように広げることができる性質をいう。線状に伸ばせる性質は延性であり、区別して覚える必要がある。","間違えやすい理由":"「延性」（引き伸ばして線にできる性質）と「展性」（打ち延ばして板にできる性質）は名前も意味も似ているため混同しやすい。","音声用文章":"展性とは、金属を打ち延ばして、薄い板のように広げることができる性質のことです。","公式分野":"機械に関する基礎的知識","詳細タグ":["金属材料","展性・延性"],"学習タグ":["間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0017","資格":"消防設備士乙6類","分野":"機械に関する基礎的知識","難易度":"標準","頻出度":4,"販売対象":true,"根拠":"参考書 第1章 Lesson7「機械材料(2)」確認テストページより作成","問題":"銅と亜鉛の合金の名称として正しいものはどれか。","選択肢A":"黄銅（真鍮）","選択肢B":"青銅（ブロンズ）","選択肢C":"ジュラルミン","選択肢D":"ステンレス鋼","正解":"A","解説":"黄銅（真鍮）は銅と亜鉛の合金である。青銅は銅とすずの合金、ジュラルミンはアルミニウムに銅などを添加した合金、ステンレス鋼は鉄にクロムやニッケルを添加した合金である。","間違えやすい理由":"黄銅（銅+亜鉛）と青銅（銅+すず）は名前が似ており、組成の元素を混同しやすい。「黄銅は亜鉛、青銅はすず」と対で覚えるとよい。","音声用文章":"黄銅、別名真鍮は、銅と亜鉛の合金です。青銅は、銅とすずの合金である点と区別して覚えましょう。","公式分野":"機械に関する基礎的知識","詳細タグ":["非鉄金属材料","合金"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0018","資格":"消防設備士乙6類","分野":"機械に関する基礎的知識","難易度":"標準","頻出度":3,"販売対象":true,"根拠":"参考書 第1章 Lesson7「機械材料(2)」確認テストページより作成","問題":"ステンレス鋼の説明として正しいものはどれか。","選択肢A":"低炭素鋼にクロムとニッケルを添加した合金である","選択肢B":"銅とすずのみの合金である","選択肢C":"鉄をまったく含まない合金である","選択肢D":"炭素含有量が非常に多い鋳鉄の一種である","正解":"A","解説":"ステンレス鋼は、低炭素鋼にクロムとニッケルを添加した合金であり、さびにくい性質（耐食性）を持つことが特徴である。","間違えやすい理由":"「ステンレス」という名前から鉄を含まない特殊な金属だと誤解しやすいが、実際は鉄鋼材料の一種であり、クロムやニッケルの添加によってさびにくくした合金である。","音声用文章":"ステンレス鋼は、低炭素鋼にクロムとニッケルを添加した合金で、さびにくい性質を持っています。","公式分野":"機械に関する基礎的知識","詳細タグ":["鉄鋼材料","ステンレス鋼"],"学習タグ":["頻出"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0019","資格":"消防設備士乙6類","分野":"機械に関する基礎的知識","難易度":"標準","頻出度":5,"販売対象":true,"根拠":"参考書 第1章 Lesson8「荷重と応力(1)」確認テストページより作成","問題":"50mm×50mmの断面の角材に5000Nの引張荷重が作用しているとき、この角材に生じる引張応力として正しいものはどれか。","選択肢A":"2MPa","選択肢B":"20MPa","選択肢C":"200MPa","選択肢D":"0.2MPa","正解":"A","解説":"応力は、荷重(N)を物体の断面積(mm²)で割ることで求められる。断面積は50mm×50mm=2500mm²。応力=5000N÷2500mm²=2N/mm²=2MPaとなる。","間違えやすい理由":"断面積の単位をmm²で計算する点や、応力の単位N/mm²がMPaと同じ値になる点を忘れると計算ミスにつながる。断面積を求める掛け算を忘れて荷重をそのまま長さで割ってしまう間違いも多い。","音声用文章":"応力は、荷重を、物体の断面積で割ることで求められます。単位はメガパスカル、またはニュートン毎平方ミリメートルです。","公式分野":"機械に関する基礎的知識","詳細タグ":["荷重と応力","計算問題"],"学習タグ":["頻出","計算問題"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0020","資格":"消防設備士乙6類","分野":"機械に関する基礎的知識","難易度":"やや難","頻出度":4,"販売対象":true,"根拠":"参考書 第1章 Lesson8「荷重と応力(2)」確認テストページより作成","問題":"応力ひずみ図において、荷重を取り除いたときに元の長さに戻る限界点を何と呼ぶか。","選択肢A":"弾性限度","選択肢B":"極限強さ","選択肢C":"許容応力","選択肢D":"安全率","正解":"A","解説":"弾性限度とは、荷重を取り除いたとき、伸びていた部分がもとに戻る限界点をいう。弾性限度を超えて荷重を加えると、荷重を取り除いても元の長さに戻らなくなる（永久ひずみが残る）。","間違えやすい理由":"「比例限度」（応力とひずみが比例関係にある限界点）と「弾性限度」（元の長さに戻る限界点）は応力ひずみ図上で近い位置にあり、意味の違いを混同しやすい。","音声用文章":"弾性限度とは、荷重を取り除いたとき、伸びていた部分が元の長さに戻る限界点のことです。","公式分野":"機械に関する基礎的知識","詳細タグ":["応力ひずみ図","弾性限度"],"学習タグ":["間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0021","資格":"消防設備士乙6類","分野":"機械に関する基礎的知識","難易度":"やや難","頻出度":4,"販売対象":true,"根拠":"参考書 第1章 Lesson8「荷重と応力(2)」確認テストページより作成","問題":"「許容応力」の説明として正しいものはどれか。","選択肢A":"材料を安全に使用することのできる最大の応力","選択肢B":"材料が破断するときの応力（極限強さ）そのもの","選択肢C":"最大荷重時の応力そのもの","選択肢D":"荷重がゼロのときの応力","正解":"A","解説":"許容応力とは、材料を安全に使用することのできる最大の応力をいう。極限強さをそのまま使用限界とせず、安全率で割ることで余裕を持たせた許容応力を設定する。","間違えやすい理由":"「極限強さ」（材料が破断する応力）と「許容応力」（安全に使用できる応力）を同じものと誤解しやすいが、許容応力は極限強さより小さく、安全率によって余裕を持たせた値である。","音声用文章":"許容応力とは、材料を安全に使用することのできる、最大の応力のことです。","公式分野":"機械に関する基礎的知識","詳細タグ":["応力ひずみ図","許容応力","安全率"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0022","資格":"消防設備士乙6類","分野":"機械に関する基礎的知識","難易度":"標準","頻出度":3,"販売対象":true,"根拠":"参考書 第1章 Lesson8「荷重と応力(1)」確認テストページより作成","問題":"ハンマーで材料を打つなど、急激に加わる荷重を何と呼ぶか。","選択肢A":"衝撃荷重","選択肢B":"静荷重","選択肢C":"交番荷重","選択肢D":"繰返し荷重","正解":"A","解説":"衝撃荷重とは、ハンマーで材料を打つなど、急激に加わる荷重のことをいう。時間的に変化しない一定の大きさの荷重は静荷重、大きさや向きが周期的に変化する荷重は交番荷重・繰返し荷重と呼ぶ。","間違えやすい理由":"静荷重・衝撃荷重・交番荷重・繰返し荷重はいずれも荷重の分類名であり、それぞれの定義（時間的変化の有無、急激さ、向きの変化）を正確に区別する必要がある。","音声用文章":"衝撃荷重とは、ハンマーで材料を打つときのように、急激に加わる荷重のことです。","公式分野":"機械に関する基礎的知識","詳細タグ":["荷重と応力","荷重の種類"],"学習タグ":["間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0023","資格":"消防設備士乙6類","分野":"消防関係法令（共通）","難易度":"標準","頻出度":5,"販売対象":true,"根拠":"参考書 第2章 Lesson1「消防法令上の用語」確認テストページより作成","問題":"「特定防火対象物」の説明として正しいものはどれか。","選択肢A":"不特定多数の者が出入りする、または避難が困難な者が入所する用途を含む防火対象物","選択肢B":"山林および舟車のみを指す","選択肢C":"延べ面積にかかわらずすべての住宅","選択肢D":"消防用設備等が設置されていない建築物","正解":"A","解説":"特定防火対象物とは、百貨店・病院・ホテルなど不特定多数の者が出入りする、または高齢者施設など避難が困難な者が入所する用途を含む防火対象物をいう。学校や共同住宅など、特定の者しか出入りしない用途は非特定防火対象物に分類される。","間違えやすい理由":"「防火対象物」と「特定防火対象物」の違いを混同しやすい。防火対象物は消防法上の建築物等全般を指す広い概念で、特定防火対象物はそのうち不特定多数が出入りする等の用途に限定した分類である。","音声用文章":"特定防火対象物とは、百貨店やホテルのように、不特定多数の者が出入りする、または避難が困難な者が入所する用途を含む防火対象物のことです。","公式分野":"消防関係法令","詳細タグ":["消防法令上の用語","特定防火対象物"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0024","資格":"消防設備士乙6類","分野":"消防関係法令（共通）","難易度":"やや難","頻出度":4,"販売対象":true,"根拠":"参考書 第2章 Lesson1「消防法令上の用語」確認テストページより作成","問題":"「無窓階」の説明として正しいものはどれか。","選択肢A":"採光上、排煙上または消火活動上有効な開口部を有しない階","選択肢B":"窓が1つもない階","選択肢C":"地下にある階すべて","選択肢D":"高さ31mを超える階","正解":"A","解説":"無窓階とは、建築物の地上階のうち、採光上、排煙上または消火活動上有効な開口部を有しない階のことをいう。単に窓が物理的に無いことではなく、有効な開口部の有無が基準となる。","間違えやすい理由":"文字通り「窓が無い階」と解釈しがちだが、実際には窓があっても、採光・排煙・消火活動上有効に機能する開口部でなければ無窓階に該当する場合がある。","音声用文章":"無窓階とは、採光上、排煙上、または消火活動上有効な開口部を有しない階のことです。","公式分野":"消防関係法令","詳細タグ":["消防法令上の用語","無窓階"],"学習タグ":["間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0025","資格":"消防設備士乙6類","分野":"消防関係法令（共通）","難易度":"標準","頻出度":4,"販売対象":true,"根拠":"参考書 第2章 Lesson2「消防の組織と火災予防」確認テストページより作成","問題":"消防職員が防火対象物への立入検査を行う際の説明として正しいものはどれか。","選択肢A":"関係者の承諾がなくても立ち入ることができる","選択肢B":"必ず事前に関係者の承諾を得なければならない","選択肢C":"裁判所の令状が必要である","選択肢D":"個人の住居には理由を問わず立ち入ることができない","正解":"A","解説":"消防職員は、火災予防のために必要がある場合、防火対象物や関係のある場所に立ち入って検査することができ、関係者の承諾を必要としない。ただし個人の住居については、関係者の承諾を得た場合、または火災発生のおそれが著しく大きく緊急の必要がある場合に限られる。","間違えやすい理由":"一般の立入検査と、個人の住居への立入りの取り扱いの違いを混同しやすい。一般の防火対象物への立入検査には承諾は不要だが、個人の住居は保護の程度が異なる。","音声用文章":"消防職員による立入検査は、関係者の承諾を得ることなく行うことができます。","公式分野":"消防関係法令","詳細タグ":["火災予防","立入検査"],"学習タグ":["頻出"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0026","資格":"消防設備士乙6類","分野":"消防関係法令（共通）","難易度":"標準","頻出度":4,"販売対象":true,"根拠":"参考書 第2章 Lesson3「防火管理者と統括防火管理者」確認テストページより作成","問題":"「統括防火管理者」が選任される場合として正しいものはどれか。","選択肢A":"高層建築物や地下街など、管理権原が複数に分かれている防火対象物で、全体についての防火管理を行う必要がある場合","選択肢B":"収容人員が10人未満の小規模な店舗である場合","選択肢C":"防火対象物が1つの管理権原者のみで管理されている場合","選択肢D":"消防用設備等が設置されていない場合","正解":"A","解説":"統括防火管理者は、高層建築物や地下街、複合用途防火対象物など、管理権原が複数の者に分かれている防火対象物において、防火対象物全体についての防火管理業務を一元的に行うために選任される。","間違えやすい理由":"防火管理者（各管理権原者ごとに選任）と統括防火管理者（管理権原が分かれた建物全体をまとめる）の役割の違いを混同しやすい。","音声用文章":"統括防火管理者は、管理権原が複数に分かれている高層建築物や地下街などで、防火対象物全体の防火管理を行うために選任されます。","公式分野":"消防関係法令","詳細タグ":["防火管理者","統括防火管理者"],"学習タグ":["頻出"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0027","資格":"消防設備士乙6類","分野":"消防関係法令（共通）","難易度":"標準","頻出度":3,"販売対象":true,"根拠":"参考書 第2章 Lesson4「防火対象物の点検、防炎規制」確認テストページより作成","問題":"防炎規制の対象となる防炎対象物品として、誤っているものはどれか。","選択肢A":"一般家庭で使用する衣類","選択肢B":"高層建築物や特定防火対象物などで使用するカーテン","選択肢C":"工事用シート","選択肢D":"じゅうたん等","正解":"A","解説":"防炎規制の対象となる防炎対象物品は、高層建築物や地下街、特定防火対象物などで使用するカーテン・じゅうたん等・工事用シートなどに限られる。一般家庭で使用する衣類は防炎規制の対象ではない。","間違えやすい理由":"防炎規制はすべてのカーテンやカーペットに一律に適用されると誤解しやすいが、実際は使用場所（高層建築物、特定防火対象物等）が限定されている点に注意が必要である。","音声用文章":"防炎規制の対象となるのは、高層建築物や特定防火対象物などで使用されるカーテン、じゅうたん等、工事用シートなどです。一般家庭の衣類は対象ではありません。","公式分野":"消防関係法令","詳細タグ":["防炎規制"],"学習タグ":["間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0028","資格":"消防設備士乙6類","分野":"消防関係法令（共通）","難易度":"やや難","頻出度":4,"販売対象":true,"根拠":"参考書 第2章 Lesson5「危険物規制」確認テストページより作成","問題":"「指定数量」の説明として正しいものはどれか。","選択肢A":"危険物の種類ごとに、その危険性を考慮して政令で定められた数量で、規制の基準となるもの","選択肢B":"すべての危険物に一律に定められた同じ数量","選択肢C":"危険物を貯蔵する容器の容積そのもの","選択肢D":"消防署が任意に決定できる数量","正解":"A","解説":"指定数量とは、危険物の種類ごとに、その危険性の程度を考慮して政令で定められた数量であり、危険物規制における基準となる。指定数量以上を貯蔵・取り扱う場合は消防法上の製造所・貯蔵所・取扱所としての規制を受ける。","間違えやすい理由":"指定数量がすべての危険物で共通の数値だと誤解しやすいが、実際には危険物の種類・品名ごとに異なる数値が定められている。","音声用文章":"指定数量とは、危険物の種類ごとに、その危険性を考慮して政令で定められた数量のことです。","公式分野":"消防関係法令","詳細タグ":["危険物規制","指定数量"],"学習タグ":["頻出"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0029","資格":"消防設備士乙6類","分野":"消防関係法令（共通）","難易度":"標準","頻出度":3,"販売対象":true,"根拠":"参考書 第2章 Lesson6「消防用設備等に関する規定(1)」確認テストページより作成","問題":"消防用設備等の設置・維持の義務を負う者として正しいものはどれか。","選択肢A":"防火対象物の関係者（所有者、管理者または占有者）","選択肢B":"消防設備士のみ","選択肢C":"消防長または消防署長","選択肢D":"近隣住民全員","正解":"A","解説":"消防用設備等の設置・維持の義務は、防火対象物の関係者（所有者、管理者または占有者）が負う。消防設備士は工事や整備を行う専門資格者であり、設置義務そのものを負う主体ではない。","間違えやすい理由":"実際に工事を行う消防設備士が設置義務を負っていると誤解しやすいが、義務を負うのはあくまで防火対象物の関係者（所有者・管理者・占有者）である。","音声用文章":"消防用設備等の設置と維持の義務を負うのは、防火対象物の関係者、つまり所有者、管理者または占有者です。","公式分野":"消防関係法令","詳細タグ":["消防用設備等","設置維持義務"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0030","資格":"消防設備士乙6類","分野":"消防関係法令（共通）","難易度":"やや難","頻出度":4,"販売対象":true,"根拠":"参考書 第2章 Lesson7「消防用設備等に関する規定(2)」確認テストページより作成","問題":"消防用設備等の設置単位の原則として正しいものはどれか。","選択肢A":"特段の規定がない限り、1棟の建築物を1つの防火対象物とみなして設置基準を適用する","選択肢B":"1つの部屋ごとに別々の防火対象物とみなす","選択肢C":"同一敷地内であれば、複数の棟をまとめて1つの防火対象物とみなす","選択肢D":"建築物の所有者が任意に設置単位を決めることができる","正解":"A","解説":"消防用設備等の設置単位は、特段の規定がない限り、1棟の建築物をもって1つの防火対象物とみなすのが原則である。ただし開口部のない耐火構造の床・壁で完全に区画されている場合など、例外的な取扱いがある。","間違えやすい理由":"同一敷地内にある複数の建物をまとめて1つの防火対象物とみなすと誤解しやすいが、原則はあくまで「1棟＝1防火対象物」であり、敷地単位ではない。","音声用文章":"消防用設備等の設置単位は、特段の規定がない限り、1棟の建築物を1つの防火対象物とみなして適用します。","公式分野":"消防関係法令","詳細タグ":["消防用設備等","設置単位"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0031","資格":"消防設備士乙6類","分野":"消防関係法令（共通）","難易度":"標準","頻出度":4,"販売対象":true,"根拠":"参考書 第2章 Lesson8「消防用設備等に関する規定(3)」確認テストページより作成","問題":"消防設備士が消防用設備等の工事に着手しようとするとき、着工届を提出する時期として正しいものはどれか。","選択肢A":"着工しようとする日の10日前まで","選択肢B":"着工と同時","選択肢C":"着工後1か月以内","選択肢D":"工事完了後","正解":"A","解説":"消防設備士は、消防用設備等の工事に着手しようとするときは、その工事に着手しようとする日の10日前までに、消防長または消防署長に着工届を提出しなければならない。","間違えやすい理由":"「設置届」（工事完了後に関係者が提出）と「着工届」（工事着手前に消防設備士が提出）を混同しやすい。届出者・提出時期・提出内容がそれぞれ異なる点を整理して覚える必要がある。","音声用文章":"消防設備士は、消防用設備等の工事に着手する日の10日前までに、着工届を消防長または消防署長に提出しなければなりません。","公式分野":"消防関係法令","詳細タグ":["消防用設備等","着工届"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0032","資格":"消防設備士乙6類","分野":"消防関係法令（共通）","難易度":"標準","頻出度":5,"販売対象":true,"根拠":"参考書 第2章 Lesson8「消防用設備等に関する規定(3)」確認テストページより作成","問題":"消防用設備等の点検のうち、機器点検と総合点検の頻度の組み合わせとして正しいものはどれか。","選択肢A":"機器点検は6か月に1回、総合点検は1年に1回","選択肢B":"機器点検は1年に1回、総合点検は6か月に1回","選択肢C":"機器点検・総合点検ともに1年に1回","選択肢D":"機器点検・総合点検ともに6か月に1回","正解":"A","解説":"消防用設備等の点検には機器点検と総合点検があり、機器点検は6か月に1回、総合点検は1年に1回行うこととされている。","間違えやすい理由":"機器点検と総合点検の頻度を逆に覚えてしまう間違いが多い。「機器（きき）は半年」「総合は1年」のように語呂で整理するとよい。","音声用文章":"消防用設備等の点検は、機器点検が6か月に1回、総合点検が1年に1回行われます。","公式分野":"消防関係法令","詳細タグ":["消防用設備等","点検"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0033","資格":"消防設備士乙6類","分野":"消防関係法令（共通）","難易度":"やや難","頻出度":4,"販売対象":true,"根拠":"参考書 第2章 Lesson9「消防用機械器具等の検定」確認テストページより作成","問題":"「型式承認」と「型式適合検定」の説明の組み合わせとして正しいものはどれか。","選択肢A":"型式承認は総務大臣が行い、型式適合検定は日本消防検定協会等が行う","選択肢B":"型式承認・型式適合検定はいずれも総務大臣が行う","選択肢C":"型式承認・型式適合検定はいずれも日本消防検定協会等が行う","選択肢D":"型式承認は都道府県知事が行い、型式適合検定は市町村長が行う","正解":"A","解説":"型式承認は、検定対象機械器具等の型式に係る形状等が、総務省令で定める技術上の規格に適合している旨を総務大臣が承認する制度である。型式適合検定は、個々の検定対象機械器具等の形状等が型式承認を受けた型式に適合しているかどうかを日本消防検定協会等が検定する制度である。","間違えやすい理由":"型式承認（型式そのものの承認、総務大臣が行う）と型式適合検定（個々の製品が承認された型式に適合するかの検定、日本消防検定協会等が行う）は、対象と実施主体の両方が異なる点を混同しやすい。","音声用文章":"型式承認は総務大臣が行い、型式適合検定は日本消防検定協会等が行います。","公式分野":"消防関係法令","詳細タグ":["検定制度","型式承認","型式適合検定"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0034","資格":"消防設備士乙6類","分野":"消防関係法令（共通）","難易度":"標準","頻出度":5,"販売対象":true,"根拠":"参考書 第2章 Lesson10「消防設備士制度」確認テストページより作成","問題":"甲種消防設備士と乙種消防設備士が行える業務の違いとして正しいものはどれか。","選択肢A":"甲種は消防用設備等の工事と整備の両方を行えるが、乙種は整備のみを行える","選択肢B":"甲種は整備のみ、乙種は工事と整備の両方を行える","選択肢C":"甲種・乙種とも工事と整備の両方を行える","選択肢D":"甲種・乙種とも整備のみを行える","正解":"A","解説":"甲種消防設備士は、消防用設備等の工事と整備の両方を行うことができる。乙種消防設備士は、整備のみを行うことができ、工事を行うことはできない。","間違えやすい理由":"甲種・乙種の違いを「対象設備の種類の違い」とだけ覚えてしまい、「工事ができるかどうか」という業務範囲の違いを見落としやすい。","音声用文章":"甲種消防設備士は、消防用設備等の工事と整備の両方を行うことができます。乙種消防設備士は、整備のみを行うことができます。","公式分野":"消防関係法令","詳細タグ":["消防設備士制度","甲種","乙種"],"学習タグ":["頻出"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0035","資格":"消防設備士乙6類","分野":"消防関係法令（共通）","難易度":"やや難","頻出度":4,"販売対象":true,"根拠":"参考書 第2章 Lesson10「消防設備士制度」確認テストページより作成","問題":"消防設備士免状の交付を受けた者が受講しなければならない講習（免状の書換えとは別の講習）の頻度として正しいものはどれか。","選択肢A":"免状交付後の最初の4月1日から2年以内、その後は5年以内ごと","選択肢B":"免状交付後、毎年必ず1回","選択肢C":"免状交付後、10年に1回のみ","選択肢D":"受講義務は特にない","正解":"A","解説":"消防設備士は、免状の交付を受けた日以後における最初の4月1日から2年以内に講習を受けなければならず、その後は当該講習を受けた日以後における最初の4月1日から5年以内ごとに講習を受けなければならない。","間違えやすい理由":"免状の「書換え」（本籍地・氏名等の変更、居住地・勤務地の都道府県知事に申請）と「講習」（業務従事者に義務付けられた知識・技術の維持のための受講）を混同しやすい。目的も期限の起算点も異なる。","音声用文章":"消防設備士は、免状交付後最初の4月1日から2年以内に講習を受け、その後は5年以内ごとに講習を受ける必要があります。","公式分野":"消防関係法令","詳細タグ":["消防設備士制度","講習"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0036","資格":"消防設備士乙6類","分野":"消防関係法令（第6類）","難易度":"標準","頻出度":5,"販売対象":true,"根拠":"参考書 第3章 Lesson1「消火器具の設置義務(1)」確認テストページより作成","問題":"地階、無窓階または3階以上の階における消火器具の設置義務が生じる床面積の基準として正しいものはどれか。","選択肢A":"床面積50㎡以上","選択肢B":"床面積150㎡以上","選択肢C":"床面積300㎡以上","選択肢D":"床面積にかかわらず必ず設置","正解":"A","解説":"地階、無窓階または3階以上の階に存する防火対象物の部分については、延べ面積にかかわらず、その階の床面積が50㎡以上の場合に消火器具の設置が義務づけられる。","間違えやすい理由":"防火対象物全体で見る通常の延べ面積基準（150㎡や300㎡）と、特定の階（地階・無窓階・3階以上）に個別に適用される床面積50㎡以上の基準を混同しやすい。","音声用文章":"地階、無窓階、または3階以上の階については、延べ面積にかかわらず、その階の床面積が50平方メートル以上であれば消火器具の設置が義務づけられます。","公式分野":"消防関係法令","詳細タグ":["消火器具の設置義務","地階・無窓階"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0037","資格":"消防設備士乙6類","分野":"消防関係法令（第6類）","難易度":"やや難","頻出度":4,"販売対象":true,"根拠":"参考書 第3章 Lesson2「消火器具の設置義務(2)」確認テストページより作成","問題":"防火対象物の主要構造部を耐火構造とし、かつ壁および天井の内装仕上げを難燃材料とした場合の、算定基準面積の扱いとして正しいものはどれか。","選択肢A":"算定基準面積の数値を2倍にすることができる","選択肢B":"算定基準面積の数値を半分にしなければならない","選択肢C":"算定基準面積には影響しない","選択肢D":"消火器具の設置が免除される","正解":"A","解説":"防火対象物の主要構造部を耐火構造とし、かつ壁および天井の内装仕上げを難燃材料とした場合は、火災の延焼・拡大が抑えられるため、能力単位を算定する際の算定基準面積の数値を2倍にすることができる。","間違えやすい理由":"「耐火構造にすると必要な消火器の数が減る」という結論は合っているが、算定基準面積を「2倍にする」のか「半分にする」のかを逆に覚えてしまう間違いが多い。基準面積が大きくなる＝必要な能力単位が少なくなる、という関係を理解する必要がある。","音声用文章":"主要構造部を耐火構造とし、内装仕上げを難燃材料とした防火対象物は、算定基準面積の数値を2倍にすることができます。","公式分野":"消防関係法令","詳細タグ":["消火器具の設置義務","算定基準面積","能力単位"],"学習タグ":["頻出","間違いやすい","計算問題"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0038","資格":"消防設備士乙6類","分野":"消防関係法令（第6類）","難易度":"標準","頻出度":5,"販売対象":true,"根拠":"参考書 第3章 Lesson3「消火器具の設置基準(1)」確認テストページより作成","問題":"消火器具（大型消火器を除く）を配置する際の、防火対象物の各部分からの歩行距離の基準として正しいものはどれか。","選択肢A":"20m以下","選択肢B":"30m以下","選択肢C":"50m以下","選択肢D":"特に基準はない","正解":"A","解説":"消火器具（大型消火器を除く）は、防火対象物の階ごとに、その階の各部分から消火器具に至る歩行距離が20m以下となるように配置する。なお、大型消火器の場合は歩行距離30m以下となるように配置する。","間違えやすい理由":"大型消火器の基準（歩行距離30m以下）と、通常の消火器具の基準（歩行距離20m以下）を混同しやすい。「大型は大きい数字（30m）」と関連づけて覚えるとよい。","音声用文章":"消火器具は、大型消火器を除き、防火対象物の各部分からの歩行距離が20メートル以下となるように配置します。大型消火器の場合は30メートル以下です。","公式分野":"消防関係法令","詳細タグ":["消火器具の設置基準","歩行距離"],"学習タグ":["頻出"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0039","資格":"消防設備士乙6類","分野":"消防関係法令（第6類）","難易度":"標準","頻出度":3,"販売対象":true,"根拠":"参考書 第3章 Lesson3「消火器具の設置基準(1)」確認テストページより作成","問題":"消火器具の設置・維持の基準として、床面からの高さの基準はどれか。","選択肢A":"1.5m以下","選択肢B":"1.2m以下","選択肢C":"2m以下","選択肢D":"特に基準はない","正解":"A","解説":"消火器具は、床面からの高さ1.5m以下の箇所に設けることとされている（消火器具の設置・維持の基準）。","間違えやすい理由":"他の設備・器具の高さ基準（例：無窓階の判定基準や別の設備の設置高さ）と数値を混同しやすい。消火器具は「1.5m以下」と正確に覚える必要がある。","音声用文章":"消火器具は、床面からの高さ1.5メートル以下の箇所に設置しなければなりません。","公式分野":"消防関係法令","詳細タグ":["消火器具の設置基準","設置高さ"],"学習タグ":["頻出"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0040","資格":"消防設備士乙6類","分野":"消防関係法令（第6類）","難易度":"やや難","頻出度":4,"販売対象":true,"根拠":"参考書 第3章 Lesson4「消火器具の設置基準(2)」確認テストページより作成","問題":"地下街等の換気について有効な開口部の面積が床面積の30分の1以下、かつその床面積が30㎡以下の居室に設置できない消火器の組み合わせとして正しいものはどれか。","選択肢A":"二酸化炭素を放射する消火器およびハロゲン化物（一部を除く）を放射する消火器","選択肢B":"水を放射する消火器および強化液を放射する消火器","選択肢C":"粉末を放射する消火器のみ","選択肢D":"泡を放射する消火器のみ","正解":"A","解説":"換気について有効な開口部の面積が床面積の30分の1以下で、かつその床面積が20㎡以下の地階、無窓階または居室には、二酸化炭素を放射する消火器やハロゲン化物（一部を除く）を放射する消火器を設置できない。窒息や中毒のおそれがあるためである。","間違えやすい理由":"「一部を除く」とされているハロゲン化物（ハロン1301を放射するものは設置できる）の例外規定を見落とし、すべてのハロゲン化物消火器が一律に設置禁止だと誤解しやすい。","音声用文章":"換気が不十分な地下街等の居室には、二酸化炭素を放射する消火器や、一部を除くハロゲン化物を放射する消火器は、酸欠や中毒のおそれがあるため設置できません。","公式分野":"消防関係法令","詳細タグ":["消火器具の設置基準","地下街等","設置禁止"],"学習タグ":["間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0041","資格":"消防設備士乙6類","分野":"消防関係法令（第6類）","難易度":"やや難","頻出度":4,"販売対象":true,"根拠":"参考書 第3章 Lesson4「消火器具の設置基準(2)」確認テストページより作成","問題":"電気設備による火災（電気火災）に対する消火器の適応性の説明として正しいものはどれか。","選択肢A":"水や強化液を棒状に放射する消火器は適応しないが、霧状に放射するものは適応する","選択肢B":"水や強化液は、棒状・霧状のいずれの放射方法でも適応する","選択肢C":"水や強化液は、棒状・霧状のいずれの放射方法でも適応しない","選択肢D":"電気火災にはどの消火器も同じように適応する","正解":"A","解説":"電気設備による火災に対しては、水や強化液を棒状に放射する消火器は感電のおそれがあるため適応しないが、霧状に放射するものは感電のおそれが少ないため適応するとされている。","間違えやすい理由":"「水は電気火災に使えない」と一律に覚えてしまいがちだが、正確には放射方法（棒状か霧状か）によって適応性が異なる点がポイントである。","音声用文章":"電気設備の火災に対して、水や強化液を棒状に放射する消火器は適応しませんが、霧状に放射するものは適応します。","公式分野":"消防関係法令","詳細タグ":["消火器具の適応性","電気火災"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0042","資格":"消防設備士乙6類","分野":"消火器の構造・機能・整備","難易度":"標準","頻出度":5,"販売対象":true,"根拠":"参考書 第4章 Lesson1「消火の理論と消火剤」確認テストページより作成","問題":"消火の4つの方法（除去・窒息・冷却・抑制）のうち、「抑制」の説明として正しいものはどれか。","選択肢A":"物質と酸素との酸化反応の連鎖を化学的に抑制することによって燃焼を中止させる方法","選択肢B":"可燃物を取り除く方法","選択肢C":"可燃物と酸素の接触を断つ方法","選択肢D":"燃焼物の温度を下げる方法","正解":"A","解説":"抑制消火（負触媒効果）とは、物質と酸素との酸化反応の連鎖を化学的に抑制することによって燃焼を中止させる方法である。ハロゲン化物消火剤や粉末消火剤の一部は、この抑制作用を主な消火メカニズムとする。","間違えやすい理由":"除去・窒息・冷却の3要素（燃焼の3要素に対応）はイメージしやすいが、「抑制」は化学的な作用であり直感的に理解しにくいため、他の3つと混同したり説明を誤って覚えやすい。","音声用文章":"抑制消火とは、酸化反応の連鎖を化学的に抑制することで燃焼を中止させる方法です。","公式分野":"消火器の構造・機能・整備","詳細タグ":["消火の理論","抑制消火"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0043","資格":"消防設備士乙6類","分野":"消火器の構造・機能・整備","難易度":"標準","頻出度":5,"販売対象":true,"根拠":"参考書 第4章 Lesson2「消火器の種類」確認テストページより作成","問題":"二酸化炭素消火器およびハロン1301消火器を除く消火器において、常に指示圧力計を取り付ける必要があるのはどの方式か。","選択肢A":"蓄圧式","選択肢B":"加圧式（ガス加圧式）","選択肢C":"反応式","選択肢D":"据置式","正解":"A","解説":"蓄圧式の消火器は、本体容器内に消火剤と圧縮ガスを共に充てんしているため、内部の圧力を確認するための指示圧力計をすべてに取り付ける必要がある（二酸化炭素消火器・ハロン1301消火器は自身の圧力で放射するため指示圧力計を取り付けない）。","間違えやすい理由":"加圧式（ガス加圧式）は加圧用ガス容器の圧力によって消火剤を放射する方式で、指示圧力計は取り付けられていない点を混同しやすい。","音声用文章":"蓄圧式の消火器は、二酸化炭素消火器とハロン1301消火器を除き、すべてに指示圧力計を取り付ける必要があります。","公式分野":"消火器の構造・機能・整備","詳細タグ":["消火器の種類","蓄圧式","指示圧力計"],"学習タグ":["頻出"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0044","資格":"消防設備士乙6類","分野":"消火器の構造・機能・整備","難易度":"やや難","頻出度":4,"販売対象":true,"根拠":"参考書 第4章 Lesson3「水消火器と強化液消火器」確認テストページより作成","問題":"強化液消火剤の性質として正しいものはどれか。","選択肢A":"炭酸カリウム等の濃厚な水溶液で、アルカリ性であり、凝固点が低く寒冷地でも使用しやすい","選択肢B":"中性の水溶液で、常温でしか使用できない","選択肢C":"酸性の水溶液で、電気火災に強い","選択肢D":"油類を主成分とする不燃性の液体である","正解":"A","解説":"強化液消火剤は、炭酸カリウム等を溶かした濃厚な水溶液で、アルカリ性を示す。凝固点がおよそ-25℃～-30℃と低く、寒冷地でも凍結しにくいため使用しやすいという特徴がある。","間違えやすい理由":"強化液が酸性だと誤解しやすいが、実際はアルカリ性である。また、凍結しやすいと誤解しやすいが、逆に凝固点を下げる加工がされているため寒冷地に適している。","音声用文章":"強化液消火剤は、炭酸カリウム等の濃厚な水溶液で、アルカリ性です。凝固点が低いため、寒冷地でも使用しやすいという特徴があります。","公式分野":"消火器の構造・機能・整備","詳細タグ":["強化液消火器","消火剤の性質"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0045","資格":"消防設備士乙6類","分野":"消火器の構造・機能・整備","難易度":"やや難","頻出度":4,"販売対象":true,"根拠":"参考書 第4章 Lesson4「泡消火器」確認テストページより作成","問題":"化学泡消火器のA剤とB剤の主成分の組み合わせとして正しいものはどれか。","選択肢A":"A剤：炭酸水素ナトリウム、B剤：硫酸アルミニウム","選択肢B":"A剤：硫酸アルミニウム、B剤：炭酸水素ナトリウム","選択肢C":"A剤：りん酸アンモニウム、B剤：炭酸水素カリウム","選択肢D":"A剤：水成膜泡剤、B剤：合成界面活性剤","正解":"A","解説":"化学泡消火器は、A剤（主成分：炭酸水素ナトリウム）とB剤（主成分：硫酸アルミニウム）の化学反応によって生じる二酸化炭素を含んだ泡を放射する。この化学反応により発生する二酸化炭素が、泡を包んで放射する圧力源にもなる。","間違えやすい理由":"A剤とB剤の成分を逆に覚えやすい。「A剤はアルカリ性の重曹（炭酸水素ナトリウム）」「B剤は硫酸アルミニウム」と、頭文字や性質と関連づけて整理する必要がある。","音声用文章":"化学泡消火器のA剤の主成分は炭酸水素ナトリウム、B剤の主成分は硫酸アルミニウムです。この2つの化学反応によって二酸化炭素を含む泡が発生します。","公式分野":"消火器の構造・機能・整備","詳細タグ":["泡消火器","化学泡消火器"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0046","資格":"消防設備士乙6類","分野":"消火器の構造・機能・整備","難易度":"やや難","頻出度":4,"販売対象":true,"根拠":"参考書 第4章 Lesson5「二酸化炭素消火器とハロン1301消火器」確認テストページより作成","問題":"二酸化炭素消火器とハロン1301消火器に共通する特徴として正しいものはどれか。","選択肢A":"いずれも高圧ガス保安法の適用を受け、消火剤自身の圧力によって放射する","選択肢B":"いずれも指示圧力計が装着されている","選択肢C":"いずれも電気火災には適応しない","選択肢D":"いずれも地下街等どこにでも設置できる","正解":"A","解説":"二酸化炭素消火器とハロン1301消火器は、いずれも高圧ガス保安法の適用を受け、消火剤自身の蒸気圧によって放射する方式であるため、指示圧力計は装着されていない。両者とも窒息効果を持ち、電気火災にも適応する。","間違えやすい理由":"他の蓄圧式消火器と同様に指示圧力計が付いていると誤解しやすいが、二酸化炭素消火器とハロン1301消火器は自身の圧力で放射するため、指示圧力計は不要という点が特殊である。","音声用文章":"二酸化炭素消火器とハロン1301消火器は、どちらも高圧ガス保安法の適用を受け、消火剤自身の圧力によって放射するため、指示圧力計は付いていません。","公式分野":"消火器の構造・機能・整備","詳細タグ":["二酸化炭素消火器","ハロン1301消火器"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0047","資格":"消防設備士乙6類","分野":"消火器の構造・機能・整備","難易度":"標準","頻出度":5,"販売対象":true,"根拠":"参考書 第4章 Lesson6「粉末消火器」確認テストページより作成","問題":"りん酸アンモニウムを主成分とする粉末消火剤が適応する火災の組み合わせとして正しいものはどれか。","選択肢A":"A火災、B火災、C火災のすべて","選択肢B":"B火災とC火災のみ","選択肢C":"A火災のみ","選択肢D":"C火災のみ","正解":"A","解説":"りん酸アンモニウムを主成分とする粉末消火剤（淡紅色に着色）は、A火災（普通火災）、B火災（油火災）、C火災（電気火災）のすべてに適応する。一方、炭酸水素塩類（炭酸水素ナトリウムや炭酸水素カリウム）を主成分とするものはB火災とC火災には適応するが、A火災には適応しない。","間違えやすい理由":"粉末消火剤には主成分によって適応火災が異なるものが複数存在する（りん酸塩系はABC全対応、炭酸水素塩系はBC対応）。この違いを混同しやすい。","音声用文章":"りん酸アンモニウムを主成分とする粉末消火剤は、A火災、B火災、C火災のすべてに適応します。","公式分野":"消火器の構造・機能・整備","詳細タグ":["粉末消火器","適応火災"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0048","資格":"消防設備士乙6類","分野":"消火器の構造・機能・整備","難易度":"標準","頻出度":4,"販売対象":true,"根拠":"参考書 第4章 Lesson8「外観点検(2)」確認テストページより作成","問題":"蓄圧式消火器の外観点検において、指示圧力計の指針が緑色範囲の下限より下がっている場合の対応として正しいものはどれか。","選択肢A":"機能点検を行う必要がある","選択肢B":"そのまま設置を継続してよい","選択肢C":"外観点検のみをやり直す","選択肢D":"廃棄するしかない","正解":"A","解説":"指示圧力計の指針が緑色範囲（適正な使用圧力範囲）の上限を超えている場合、または下限より下がっている場合は、機能点検を行う必要がある。","間違えやすい理由":"外観点検の範囲内で完結する対応（清掃や部品交換）で済むと考えがちだが、圧力の異常は消火器の機能そのものに関わるため、より詳細な機能点検が必要になる点がポイント。","音声用文章":"指示圧力計の指針が緑色範囲の上限より上がっている、または下限より下がっている場合は、機能点検を行う必要があります。","公式分野":"消火器の構造・機能・整備","詳細タグ":["外観点検","指示圧力計"],"学習タグ":["頻出"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0049","資格":"消防設備士乙6類","分野":"消火器の構造・機能・整備","難易度":"やや難","頻出度":5,"販売対象":true,"根拠":"参考書 第4章 Lesson9「機能点検の概要」確認テストページより作成","問題":"化学泡消火器の機能点検は、製造年からどのくらい経過したものについて実施するか。","選択肢A":"1年を経過したものについて全数実施する","選択肢B":"3年を経過したものについて全数実施する","選択肢C":"5年を経過したものについて抜取り方式で実施する","選択肢D":"機能点検は不要である","正解":"A","解説":"化学泡消火器は、製造年から1年を経過したものについて機能点検を実施する。化学泡消火器は薬剤の劣化が早いため、他の消火器（加圧式は3年、蓄圧式は5年）と比べて点検の頻度が高く設定されている。","間違えやすい理由":"加圧式消火器（二酸化炭素・ハロゲン化物を除く）の3年、蓄圧式消火器の5年という基準と混同しやすい。化学泡消火器は薬剤の性質上、最も短い1年という点が特徴である。","音声用文章":"化学泡消火器は、製造年から1年を経過したものについて、全数を対象に機能点検を実施します。","公式分野":"消火器の構造・機能・整備","詳細タグ":["機能点検","化学泡消火器"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0050","資格":"消防設備士乙6類","分野":"消火器の構造・機能・整備","難易度":"やや難","頻出度":4,"販売対象":true,"根拠":"参考書 第4章 Lesson9「機能点検の概要」確認テストページより作成","問題":"蓄圧式の粉末消火器で抜取り方式による機能点検を行う場合、対象とならないものはどれか。","選択肢A":"製造年から10年を超えたもの","選択肢B":"製造年から10年以内のもの","選択肢C":"同一製造年のもの","選択肢D":"メーカーが同一のもの","正解":"A","解説":"抜取り方式は、蓄圧式のうち粉末消火器の場合、製造年から10年を超えるものについては対象とならず、全数を対象として機能点検を行う必要がある。10年以内のものについては抜取り方式で点検できる。","間違えやすい理由":"抜取り方式が使える条件（製造年から10年以内）と使えない条件（10年超は全数点検）を逆に覚えやすい。","音声用文章":"蓄圧式の粉末消火器で、製造年から10年を超えるものは、抜取り方式ではなく全数を対象として機能点検を行います。","公式分野":"消火器の構造・機能・整備","詳細タグ":["機能点検","抜取り方式"],"学習タグ":["間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0051","資格":"消防設備士乙6類","分野":"消火器の構造・機能・整備","難易度":"標準","頻出度":3,"販売対象":true,"根拠":"参考書 第4章 Lesson10「消火器の分解の手順」確認テストページより作成","問題":"排圧栓のない蓄圧式消火器を分解する際、残圧を排出するための操作として正しいものはどれか。","選択肢A":"安全栓を外し、レバーを握って排出する","選択肢B":"排圧栓を開いて排出する","選択肢C":"本体容器を逆さにして振る","選択肢D":"特に何もせず分解してよい","正解":"A","解説":"排圧栓のない蓄圧式消火器を分解する場合は、安全栓を外し、レバーを握って残圧を排出する。排圧栓があるものは、まず排圧栓を開いて残圧を排出してから分解する。","間違えやすい理由":"排圧栓の有無によって残圧排出の手順が異なる点を混同しやすい。排圧栓がある場合とない場合の手順をそれぞれ正確に区別して覚える必要がある。","音声用文章":"排圧栓のない蓄圧式消火器は、安全栓を外し、レバーを握って残圧を排出してから分解します。","公式分野":"消火器の構造・機能・整備","詳細タグ":["消火器の分解","残圧排出"],"学習タグ":["頻出"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0052","資格":"消防設備士乙6類","分野":"消火器の規格","難易度":"標準","頻出度":5,"販売対象":true,"根拠":"参考書 第5章 Lesson1「消火器の技術上の規格(1)」確認テストページより作成","問題":"大型消火器に該当するための能力単位の基準として正しいものはどれか。","選択肢A":"A火災に適応するものは能力単位10単位以上、B火災に適応するものは20単位以上","選択肢B":"A火災・B火災とも能力単位5単位以上","選択肢C":"A火災に適応するものは能力単位20単位以上、B火災に適応するものは10単位以上","選択肢D":"能力単位の基準はなく、薬剤量のみで判定する","正解":"A","解説":"大型消火器に該当するためには、A火災に適応するものは能力単位10単位以上、B火災に適応するものは20単位以上であることが基準とされている（この能力単位に加え、規定の薬剤充てん量以上であることも必要）。","間違えやすい理由":"A火災とB火災の基準数値（10単位・20単位）を逆に覚えやすい。","音声用文章":"大型消火器は、A火災に適応するものは能力単位10単位以上、B火災に適応するものは20単位以上であることが基準です。","公式分野":"消火器の規格","詳細タグ":["消火器の規格","能力単位","大型消火器"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0053","資格":"消防設備士乙6類","分野":"消火器の規格","難易度":"やや難","頻出度":4,"販売対象":true,"根拠":"参考書 第5章 Lesson1「消火器の技術上の規格(1)」確認テストページより作成","問題":"大型消火器の消火薬剤充てん量の基準の組み合わせとして、誤っているものはどれか。","選択肢A":"化学泡消火器：80kg以上","選択肢B":"強化液消火器：60ℓ以上","選択肢C":"二酸化炭素消火器：50kg以上","選択肢D":"粉末消火器：20kg以上","正解":"A","解説":"大型の化学泡消火器の薬剤充てん量は「80ℓ以上」であり、「80kg以上」ではない。液体の消火薬剤はℓ（リットル）、粉末や二酸化炭素などの消火薬剤はkgで表される点に注意する。強化液は60ℓ以上、二酸化炭素は50kg以上、粉末は20kg以上が基準である。","間違えやすい理由":"液体薬剤の単位（ℓ）と粉末・気体薬剤の単位（kg）を混同しやすい。化学泡消火剤は液体だがℓ表記であることを正確に覚える必要がある。","音声用文章":"大型の化学泡消火器の薬剤充てん量は、80キログラムではなく、80リットル以上です。単位の違いに注意しましょう。","公式分野":"消火器の規格","詳細タグ":["消火器の規格","大型消火器","薬剤充てん量"],"学習タグ":["頻出","間違いやすい","計算問題"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0054","資格":"消防設備士乙6類","分野":"消火器の規格","難易度":"標準","頻出度":5,"販売対象":true,"根拠":"参考書 第5章 Lesson2「消火器の技術上の規格(2)」確認テストページより作成","問題":"手さげ式消火器（住宅用消火器を除く）の操作の機構として正しいものはどれか。","選択肢A":"1動作で放射を開始できるものでなければならない","選択肢B":"2動作以内で放射を開始できるものでなければならない","選択肢C":"3動作以内で放射を開始できるものでなければならない","選択肢D":"動作数の制限はない","正解":"A","解説":"手さげ式消火器（住宅用消火器を除く）は、すべて1動作で放射を開始できるものでなければならない。車載式消火器は、安全栓を引き抜く動作、ホースを外す動作を含めて3動作以内とされている。","間違えやすい理由":"手さげ式の1動作と、車載式の3動作以内という基準を混同しやすい。運搬方式によって基準が異なる点に注意が必要である。","音声用文章":"手さげ式消火器は、住宅用消火器を除き、すべて1動作で放射を開始できるものでなければなりません。","公式分野":"消火器の規格","詳細タグ":["消火器の規格","操作の機構"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0055","資格":"消防設備士乙6類","分野":"消火器の規格","難易度":"標準","頻出度":4,"販売対象":true,"根拠":"参考書 第5章 Lesson2「消火器の技術上の規格(2)」確認テストページより作成","問題":"消火器の放射性能の基準として正しいものはどれか（放射時間・放射距離）。","選択肢A":"温度20℃において放射時間は10秒以上、放射距離は消火に有効な距離を有すること","選択肢B":"放射時間は1分以上でなければならない","選択肢C":"放射距離は必ず3m以上でなければならない","選択肢D":"放射時間・放射距離とも基準はない","正解":"A","解説":"消火器の放射性能は、温度20℃において放射時間が10秒以上であり、消火に有効な放射距離を有するものでなければならないとされている。","間違えやすい理由":"放射距離について「必ず3m以上」のような固定値があると誤解しやすいが、規格上は「消火に有効な距離」という表現であり、消火器の種類によって実際の放射距離は異なる。","音声用文章":"消火器の放射時間は、温度20℃において10秒以上であり、消火に有効な放射距離を有する必要があります。","公式分野":"消火器の規格","詳細タグ":["消火器の規格","放射性能"],"学習タグ":["頻出"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0056","資格":"消防設備士乙6類","分野":"消火器の規格","難易度":"やや難","頻出度":4,"販売対象":true,"根拠":"参考書 第5章 Lesson2「消火器の技術上の規格(2)」確認テストページより作成","問題":"消火器の使用温度範囲の基準（化学泡消火器を除く）として正しいものはどれか。","選択肢A":"0℃以上40℃以下","選択肢B":"5℃以上40℃以下","選択肢C":"-10℃以上50℃以下","選択肢D":"10℃以上35℃以下","正解":"A","解説":"消火器の使用温度範囲は、規格省令により0℃以上40℃以下と定められている（化学泡消火器のみ例外的に5℃以上40℃以下）。","間違えやすい理由":"化学泡消火器の使用温度範囲（5℃以上40℃以下）と、それ以外の消火器の使用温度範囲（0℃以上40℃以下）の下限温度を混同しやすい。","音声用文章":"消火器の使用温度範囲は、化学泡消火器を除き、0℃以上40℃以下と定められています。","公式分野":"消火器の規格","詳細タグ":["消火器の規格","使用温度範囲"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0057","資格":"消防設備士乙6類","分野":"消火器の規格","難易度":"標準","頻出度":4,"販売対象":true,"根拠":"参考書 第5章 Lesson3「部品に関する規格(1)」確認テストページより作成","問題":"安全栓のリング部の内径の基準として正しいものはどれか。","選択肢A":"2cm以上","選択肢B":"1cm以上","選択肢C":"5cm以上","選択肢D":"特に基準はない","正解":"A","解説":"安全栓のリング部の内径は、2cm以上とされている。安全栓は、みだりに分解したり調整したりできないものでなければならない。","間違えやすい理由":"他の部品（安全弁の口径など）の数値と混同しやすい。安全栓のリング内径は「2cm以上」と正確に覚える必要がある。","音声用文章":"安全栓のリング部の内径は、2センチメートル以上とされています。","公式分野":"消火器の規格","詳細タグ":["消火器の規格","安全栓"],"学習タグ":["頻出"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0058","資格":"消防設備士乙6類","分野":"消火器の規格","難易度":"やや難","頻出度":4,"販売対象":true,"根拠":"参考書 第5章 Lesson4「部品に関する規格(2)」確認テストページより作成","問題":"指示圧力計の指示圧力範囲の許容誤差の基準として正しいものはどれか。","選択肢A":"使用圧力値の上下15%以内","選択肢B":"使用圧力値の上下50%以内","選択肢C":"使用圧力値と全く同じでなければならない","選択肢D":"特に基準はない","正解":"A","解説":"指示圧力計の指示圧力範囲は、使用圧力値の上下15%以内とすることとされている。なお、指示圧力計の使用圧力範囲は、いずれも0.7～0.98MPaとされている。","間違えやすい理由":"「使用圧力範囲（0.7～0.98MPa）」という固定の数値と、「指示圧力範囲の許容誤差（使用圧力値の上下15%以内）」という別の基準を混同しやすい。","音声用文章":"指示圧力計の指示圧力範囲は、使用圧力値の上下15パーセント以内とされています。","公式分野":"消火器の規格","詳細タグ":["消火器の規格","指示圧力計"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0059","資格":"消防設備士乙6類","分野":"消火器の規格","難易度":"標準","頻出度":5,"販売対象":true,"根拠":"参考書 第5章 Lesson5「部品に関する規格(3)」確認テストページより作成","問題":"消火器の外面の塗色に関する基準として正しいものはどれか。","選択肢A":"外面の25%以上を赤色仕上げとしなければならない","選択肢B":"外面全体を必ず赤色にしなければならない","選択肢C":"外面の50%以上を赤色仕上げとしなければならない","選択肢D":"塗色に関する基準はない","正解":"A","解説":"消火器の外面は、その25%以上を赤色仕上げとしなければならないとされている（二酸化炭素消火器は本体容器の高圧ガス保安法の適用により、緑色を25%以上塗色することとされている）。","間違えやすい理由":"消火器＝全面赤色というイメージから、外面全体を赤くする必要があると誤解しやすいが、規格上は「25%以上」という下限が定められているに過ぎない。","音声用文章":"消火器の外面は、その25パーセント以上を赤色仕上げとしなければなりません。","公式分野":"消火器の規格","詳細タグ":["消火器の規格","塗色"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0060","資格":"消防設備士乙6類","分野":"消火器の規格","難易度":"やや難","頻出度":4,"販売対象":true,"根拠":"参考書 第5章 Lesson5「部品に関する規格(3)」確認テストページより作成","問題":"消火器に表示する適応火災の絵表示の地色の組み合わせとして正しいものはどれか。","選択肢A":"A火災（普通火災）：白色地　B火災（油火災）：黄色地　C火災（電気火災）：青色地","選択肢B":"A火災：黄色地　B火災：白色地　C火災：青色地","選択肢C":"A火災：青色地　B火災：黄色地　C火災：白色地","選択肢D":"A火災・B火災・C火災とも同じ地色である","正解":"A","解説":"適応火災の絵表示は、A火災（普通火災）は地色が白色で炎が赤色、可燃物が黒色。B火災（油火災）は地色が黄色で炎が赤色、可燃物が黒色。C火災（電気火災）は地色が青色で電気の閃光が黄色とされている。","間違えやすい理由":"A火災・B火災・C火災それぞれの地色（白・黄・青）を混同しやすい。「油は黄、電気は青」のように語呂で整理するとよい。","音声用文章":"適応火災の絵表示は、A火災が白色地、B火災が黄色地、C火災が青色地とされています。","公式分野":"消火器の規格","詳細タグ":["消火器の規格","絵表示"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0061","資格":"消防設備士乙6類","分野":"消火器の規格","難易度":"やや難","頻出度":3,"販売対象":true,"根拠":"参考書 第5章 Lesson6「消火薬剤に関する規格」確認テストページより作成","問題":"消火薬剤（消火器用）に共通して求められる性状として、誤っているものはどれか。","選択肢A":"著しい毒性または腐食性を有すること","選択肢B":"著しい毒性または腐食性を有しないこと","選択肢C":"腐食性のあるガスを発生しないものであること","選択肢D":"再利用消火薬剤は、適合する処理をしたものであること","正解":"A","解説":"消火薬剤は、著しい毒性または腐食性を「有しないもの」であって、かつ腐食性のあるガスを発生しないものでなければならない。「有すること」は誤りで、正しくは「有しないこと」である。","間違えやすい理由":"文章の否定表現（「有しない」）を見落とし、逆の意味（「有する」）で覚えてしまう間違いが起こりやすい。","音声用文章":"消火薬剤は、著しい毒性または腐食性を有しないものであって、かつ腐食性のあるガスを発生しないものでなければなりません。","公式分野":"消火器の規格","詳細タグ":["消火器の規格","消火薬剤"],"学習タグ":["間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0062","資格":"消防設備士乙6類","分野":"鑑別等（実技）","難易度":"標準","頻出度":5,"販売対象":true,"根拠":"参考書 実技試験対策「1 消火器本体に関する実技試験対策」問題1・4より作成","問題":"蓄圧式強化液消火器の本体に必ず装着されている計器の名称と、その計器が示すものの組み合わせとして正しいものはどれか。","選択肢A":"指示圧力計であり、消火器内部の圧力を示す","選択肢B":"温度計であり、消火器の周囲温度を示す","選択肢C":"流量計であり、放射中の流量を示す","選択肢D":"指示圧力計であり、消火薬剤の残量（重量）を示す","正解":"A","解説":"蓄圧式の消火器には指示圧力計が必ず装着されており、消火器内部の圧力（蓄圧されているガスの圧力）を示す。実技試験（鑑別）では、消火器の写真を見て「この計器の名称は」「何を示すか」を答えさせる形式で頻出する。","間違えやすい理由":"「圧力計＝薬剤の残量を示す」と誤解しやすいが、指示圧力計はあくまで内部の圧力を示すものであり、薬剤の残量そのものを直接示すものではない。","音声用文章":"蓄圧式消火器に装着されている指示圧力計は、消火器内部の圧力を示します。","公式分野":"鑑別等（実技）","詳細タグ":["実技試験","指示圧力計","蓄圧式"],"学習タグ":["頻出"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0063","資格":"消防設備士乙6類","分野":"鑑別等（実技）","難易度":"標準","頻出度":4,"販売対象":true,"根拠":"参考書 実技試験対策「1 消火器本体に関する実技試験対策」問題2より作成","問題":"機械泡消火器のノズルの名称と、この消火器が電気火災に適応しない理由の組み合わせとして正しいものはどれか。","選択肢A":"発泡ノズルであり、普通火災・油火災には適応するが、泡を伝って感電する危険性があるため電気火災には適応しない","選択肢B":"棒状ノズルであり、水を多く含むため凍結の危険性があるため電気火災には適応しない","選択肢C":"霧状ノズルであり、視界を悪くするため電気火災には適応しない","選択肢D":"発泡ノズルであり、消火に時間がかかるため電気火災には適応しない","正解":"A","解説":"機械泡消火器のノズルは発泡ノズルと呼ばれる。機械泡消火剤は普通火災・油火災には適応するが、泡（水分を含む）を伝って感電する危険性があるため、電気火災には適応しない。","間違えやすい理由":"泡は油の上に浮いて窒息効果を発揮するイメージが強く、感電のリスクを見落としやすい。泡も水分を含む以上、電気を通す媒体になり得る点がポイントである。","音声用文章":"機械泡消火器のノズルは発泡ノズルと呼ばれます。泡を伝って感電する危険性があるため、電気火災には適応しません。","公式分野":"鑑別等（実技）","詳細タグ":["実技試験","機械泡消火器","電気火災"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0064","資格":"消防設備士乙6類","分野":"鑑別等（実技）","難易度":"やや難","頻出度":4,"販売対象":true,"根拠":"参考書 実技試験対策「1 消火器本体に関する実技試験対策」問題4・5より作成","問題":"二酸化炭素消火器とハロン1301消火器の塗色に関する説明として正しいものはどれか。","選択肢A":"二酸化炭素消火器は容器の2分の1以上を緑色に、ハロン1301消火器は容器の2分の1以上をねずみ色に塗色する","選択肢B":"二酸化炭素消火器は容器全体を緑色に、ハロン1301消火器は容器全体をねずみ色に塗色する","選択肢C":"二酸化炭素消火器・ハロン1301消火器とも、塗色に関する規定はない","選択肢D":"二酸化炭素消火器はねずみ色、ハロン1301消火器は緑色に塗色する","正解":"A","解説":"二酸化炭素消火器は高圧ガス保安法の適用を受け、容器の2分の1以上を緑色に塗色することとされている。ハロン1301消火器も同様に、容器の2分の1以上をねずみ色に塗色することとされている。いずれも「全体」ではなく「2分の1以上」という基準である。","間違えやすい理由":"二酸化炭素とハロン1301の塗色（緑色とねずみ色）を逆に覚えたり、「全体を塗る」と誤解しやすい。","音声用文章":"二酸化炭素消火器は容器の2分の1以上を緑色に、ハロン1301消火器は容器の2分の1以上をねずみ色に塗色します。","公式分野":"鑑別等（実技）","詳細タグ":["実技試験","二酸化炭素消火器","ハロン1301消火器","塗色"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0065","資格":"消防設備士乙6類","分野":"鑑別等（実技）","難易度":"標準","頻出度":4,"販売対象":true,"根拠":"参考書 実技試験対策「1 消火器本体に関する実技試験対策」問題6より作成","問題":"化学泡消火器の断面図において、「消火薬剤中のごみなどによってホースやノズルが目詰まりすることを防ぐ」役割を持つ部品の名称はどれか。","選択肢A":"ろ過網","選択肢B":"内筒","選択肢C":"提手","選択肢D":"本体容器（外筒）","正解":"A","解説":"ろ過網は、消火薬剤中のごみなどによってホースやノズルが目詰まりすることを防ぐ役割を持つ部品であり、化学泡消火器などに装着されている。","間違えやすい理由":"「ろ過網」という名称から浄水フィルターのようなものとイメージしがちだが、正確には「ホース・ノズルの目詰まり防止」という機能で覚える必要がある。","音声用文章":"ろ過網は、消火薬剤中のごみなどによって、ホースやノズルが目詰まりすることを防ぐ役割を持っています。","公式分野":"鑑別等（実技）","詳細タグ":["実技試験","化学泡消火器","ろ過網"],"学習タグ":["頻出"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0066","資格":"消防設備士乙6類","分野":"鑑別等（実技）","難易度":"標準","頻出度":4,"販売対象":true,"根拠":"参考書 実技試験対策「2 消火器の部品等に関する実技試験対策」問題2より作成","問題":"消火器の安全弁の役割として正しいものはどれか。","選択肢A":"容器の内圧が急激に上昇したときに、圧力を排出する","選択肢B":"消火器を持ち運びやすくする","選択肢C":"消火剤の放射量を調整する","選択肢D":"消火器が未使用であることを示す","正解":"A","解説":"安全弁は、容器の内圧が急激に上昇したときに、圧力を排出することで容器の破裂を防ぐ役割を持つ部品である。","間違えやすい理由":"「安全栓」（レバーを不用意に握れないようにするピン状の部品）と「安全弁」（内圧上昇時に圧力を逃がす部品）の名称が似ており、役割を混同しやすい。","音声用文章":"安全弁は、容器の内圧が急激に上昇したときに、圧力を排出する役割を持っています。","公式分野":"鑑別等（実技）","詳細タグ":["実技試験","安全弁"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0067","資格":"消防設備士乙6類","分野":"鑑別等（実技）","難易度":"やや難","頻出度":3,"販売対象":true,"根拠":"参考書 実技試験対策「2 消火器の部品等に関する実技試験対策」問題3より作成","問題":"加圧用ガス容器に表示されている「TW285」という表示の意味として正しいものはどれか。","選択肢A":"容器（バルブ等を含む）の総質量が285gであること","選択肢B":"内部の圧縮ガスの圧力が285MPaであること","選択肢C":"製造から285日が経過していること","選択肢D":"容器の内容積が285cm³であること","正解":"A","解説":"加圧用ガス容器の「TW」の表示は、容器（バルブ等を含む）の総質量（Total Weight）を示しており、「TW285」は総質量285gであることを意味する。","間違えやすい理由":"「TW」がTotal Weight（総質量）の略であることを知らないと、圧力や日数など他の数値だと誤解しやすい。","音声用文章":"加圧用ガス容器の「TW」という表示は、容器の総質量を示しています。TW285は、総質量285グラムという意味です。","公式分野":"鑑別等（実技）","詳細タグ":["実技試験","加圧用ガス容器","TW表示"],"学習タグ":["間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0068","資格":"消防設備士乙6類","分野":"鑑別等（実技）","難易度":"標準","頻出度":4,"販売対象":true,"根拠":"参考書 実技試験対策「3 器具に関する実技試験対策」問題1・2・3より作成","問題":"消火器の整備に使用する器具とその用途の組み合わせとして、誤っているものはどれか。","選択肢A":"反射鏡（点検鏡）：消火器のキャップの開閉などの作業を行う","選択肢B":"クランプ台：消火器の本体容器を固定するための器具","選択肢C":"標準圧力計：蓄圧式消火器の内圧を測定し、指示圧力計の精度を確認するための器具","選択肢D":"反射鏡（点検鏡）：消火器本体容器の内面の腐食等を目視で確認するための器具","正解":"A","解説":"反射鏡（点検鏡）は、消火器本体容器の内面の腐食等を目視で確認するための器具である。「消火器のキャップの開閉などの作業を行う」のはクランプ台の役割であり、反射鏡の説明としては誤りである。","間違えやすい理由":"クランプ台（固定）と反射鏡（内部確認）の用途を入れ替えて覚えてしまう間違いが多い。それぞれの器具の見た目と役割をセットで覚える必要がある。","音声用文章":"反射鏡、別名点検鏡は、消火器本体容器の内面の腐食等を目視で確認するための器具です。キャップの開閉作業に使うのはクランプ台です。","公式分野":"鑑別等（実技）","詳細タグ":["実技試験","整備器具","クランプ台","反射鏡"],"学習タグ":["頻出","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0069","資格":"消防設備士乙6類","分野":"鑑別等（実技）","難易度":"やや難","頻出度":4,"販売対象":true,"根拠":"参考書 実技試験対策「4 実技試験対策実践編」問題6より作成","問題":"消火器を分解し、消火薬剤を再充てんする際に使用する器具の組み合わせとして正しいものはどれか。","選択肢A":"ドライバー、クランプ台、キャップスパナ、プライヤ","選択肢B":"反射鏡、標準圧力計のみ","選択肢C":"着火器具、温度計のみ","選択肢D":"特別な器具は不要である","正解":"A","解説":"ガス加圧式粉末消火器を分解し、消火薬剤を再充てんする際には、ドライバー、クランプ台、キャップスパナ、プライヤの4つの器具を使用する。","間違えやすい理由":"反射鏡や標準圧力計は点検（内部確認・圧力確認）に使う器具であり、分解・再充てん作業に使う器具（ドライバー等）とは用途が異なる点を区別する必要がある。","音声用文章":"消火器を分解して消火薬剤を再充てんする際には、ドライバー、クランプ台、キャップスパナ、プライヤの4つの器具を使用します。","公式分野":"鑑別等（実技）","詳細タグ":["実技試験","分解・再充てん","整備器具"],"学習タグ":["頻出"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0070","資格":"消防設備士乙6類","分野":"鑑別等（実技）","難易度":"やや難","頻出度":3,"販売対象":true,"根拠":"参考書 実技試験対策「4 実技試験対策実践編」問題4より作成","問題":"ハロン1301消火器、蓄圧式強化液消火器、蓄圧式機械泡消火器のうち、最低使用可能温度が最も低いものはどれか。","選択肢A":"ハロン1301消火器（-30℃）","選択肢B":"蓄圧式強化液消火器（-20℃）","選択肢C":"蓄圧式機械泡消火器（-20℃）","選択肢D":"3つとも同じ温度である","正解":"A","解説":"ハロン1301消火器は最低使用可能温度が-30℃と、他の消火器（蓄圧式強化液消火器・蓄圧式機械泡消火器はいずれも-20℃）と比べて最も低い。","間違えやすい理由":"強化液消火器の凝固点が低いことから、強化液消火器が最も低温に強いと誤解しやすいが、実際にはハロン1301消火器の方がさらに低温での使用が可能である。","音声用文章":"ハロン1301消火器の最低使用可能温度はマイナス30度で、蓄圧式強化液消火器や蓄圧式機械泡消火器のマイナス20度よりも低いです。","公式分野":"鑑別等（実技）","詳細タグ":["実技試験","使用可能温度","比較"],"学習タグ":["間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-0071","資格":"消防設備士乙6類","分野":"鑑別等（実技）","難易度":"やや難","頻出度":4,"販売対象":true,"根拠":"参考書 実技試験対策「4 実技試験対策実践編」問題7より作成（計算問題）","問題":"ある蓄圧式粉末消火器（総質量5kg、薬剤質量3kg、加圧用ガスの質量40g）について、放射試験を行ったところ、消火器の総質量は2.2kgに減った。この消火器から放射された薬剤量として正しいものはどれか（規格省令上、薬剤量の90%以上を放射することが必要）。なお、加圧用ガス0.04kgは全量放射されたものとする。","選択肢A":"0.24kg（放射された薬剤量。適合である）","選択肢B":"2.8kg（放射された薬剤量。不適合である）","選択肢C":"3kg（放射された薬剤量。適合である）","選択肢D":"2.76kg（放射された薬剤量。不適合である）","正解":"A","解説":"総質量5kg－放射後の総質量2.2kg＝2.8kg（薬剤とガスの放出分の合計）。ここから加圧用ガスの質量0.04kgを引くと2.76kg（放射された薬剤量）。もとの薬剤量3kgから2.76kgを引くと、放射されなかった薬剤量は0.24kg。薬剤量3kgの90%は2.7kgであり、放射された薬剤量2.76kgはこれを上回るため適合である。","間違えやすい理由":"「放射された薬剤量」を求める設問と、「放射されなかった薬剤量」を求める設問を混同しやすい。また、計算の途中で加圧用ガスの質量を引き忘れる間違いも多い。","音声用文章":"消火器の総質量の減少分から加圧用ガスの質量を引くと、放射された薬剤量が求められます。薬剤量の90パーセント以上が放射されていれば適合です。","公式分野":"鑑別等（実技）","詳細タグ":["実技試験","放射性能","計算問題"],"学習タグ":["頻出","計算問題","間違いやすい"],"教材":"ユーキャン","形式":"4択"},{"id":"shobo6-multi-0001","資格":"消防設備士乙6類","教材":"ユーキャン","分野":"機械に関する基礎的知識","公式分野":"機械に関する基礎的知識","難易度":"標準","頻出度":4,"販売対象":true,"形式":"複数選択","問題":"力について正しいものを2つ選んでください。","選択肢A":"力の3要素には方向が含まれる","選択肢B":"力の3要素には時間が含まれる","選択肢C":"力の3要素には作用点が含まれる","選択肢D":"力の大きさは常に質量と等しい","正解":["A","C"],"解説":"力は大きさ・方向・作用点の3要素で表します。時間は含まれず、力と質量は同じ量ではありません。","間違えやすい理由":"力の大きさと質量は関係しますが、同じ単位・同じ量ではありません。","音声用文章":"力の3要素は、大きさ、方向、作用点です。","詳細タグ":["力学","力の3要素"],"学習タグ":["頻出","複数選択"]},{"id":"shobo6-multi-0002","資格":"消防設備士乙6類","教材":"ユーキャン","分野":"機械に関する基礎的知識","公式分野":"機械に関する基礎的知識","難易度":"標準","頻出度":4,"販売対象":true,"形式":"複数選択","問題":"仕事について正しいものを2つ選んでください。","選択肢A":"仕事は力と移動距離の積で求める","選択肢B":"仕事の単位にはジュールを用いる","選択肢C":"物体が移動しなくても必ず仕事をしたことになる","選択肢D":"仕事率と仕事は常に同じ値になる","正解":["A","B"],"解説":"力の向きに物体が移動したとき、仕事は力と移動距離の積で表し、単位はジュールです。","間違えやすい理由":"力を加えても物体が移動しなければ、力学上の仕事は0です。","音声用文章":"仕事は力かける移動距離で、単位はジュールです。","詳細タグ":["力学","仕事"],"学習タグ":["頻出","複数選択"]},{"id":"shobo6-multi-0003","資格":"消防設備士乙6類","教材":"ユーキャン","分野":"機械に関する基礎的知識","公式分野":"機械に関する基礎的知識","難易度":"標準","頻出度":4,"販売対象":true,"形式":"複数選択","問題":"圧力について正しいものを2つ選んでください。","選択肢A":"圧力は単位面積当たりに働く力である","選択肢B":"1Paは1N/㎡である","選択肢C":"同じ力なら面積が大きいほど圧力は大きい","選択肢D":"圧力は力に面積を掛けて求める","正解":["A","B"],"解説":"圧力は力を面積で割って求めます。1Paは1㎡当たり1Nの力が働く圧力です。","間違えやすい理由":"同じ力なら、面積が小さいほど圧力は大きくなります。","音声用文章":"圧力は力割る面積で、1パスカルは1ニュートン毎平方メートルです。","詳細タグ":["圧力","単位"],"学習タグ":["頻出","複数選択"]},{"資格":"消防設備士乙6類","教材":"公論出版","分野":"消防関係法令（共通）","難易度":"標準","販売対象":true,"公開前確認":true,"公式分野":"消防関係法令","形式":"4択","id":"koron-0001","問題":"次のうち、特定防火対象物に該当しないものはどれか。","選択肢A":"小学校","選択肢B":"物品販売店舗","選択肢C":"旅館","選択肢D":"蒸気浴場・熱気浴場などの公衆浴場","正解":"A","解説":"小学校は非特定防火対象物です。物品販売店舗、旅館、蒸気浴場・熱気浴場などは特定防火対象物に該当します。","間違えやすい理由":"幼稚園は特定防火対象物ですが、小学校は非特定です。学校種別をまとめて覚えないことがポイントです。","音声用文章":"特定防火対象物に該当しないものは、小学校です。幼稚園との違いに注意します。","詳細タグ":["防火対象物","特定防火対象物","学校"],"学習タグ":["頻出","間違いやすい"],"頻出度":5,"根拠":"公論出版「消防設備士 第6類 501問」令和8年版 p.19 問1・p.20 正解解説（IMG_0746・IMG_0747）"},{"資格":"消防設備士乙6類","教材":"公論出版","分野":"消防関係法令（共通）","難易度":"標準","販売対象":true,"公開前確認":true,"公式分野":"消防関係法令","形式":"4択","id":"koron-0002","問題":"次のうち、特定防火対象物に該当するものはどれか。","選択肢A":"小学校","選択肢B":"共同住宅","選択肢C":"百貨店","選択肢D":"図書館","正解":"C","解説":"百貨店は特定防火対象物です。小学校、共同住宅、図書館は非特定防火対象物に分類されます。","間違えやすい理由":"人が集まる施設でも、すべてが特定防火対象物になるわけではありません。","音声用文章":"百貨店は特定防火対象物です。小学校、共同住宅、図書館は非特定です。","詳細タグ":["防火対象物","特定防火対象物","百貨店"],"学習タグ":["頻出"],"頻出度":4,"根拠":"公論出版「消防設備士 第6類 501問」令和8年版 p.19 問2・p.20 正解解説（IMG_0746・IMG_0747）"},{"資格":"消防設備士乙6類","教材":"公論出版","分野":"消防関係法令（共通）","難易度":"標準","販売対象":true,"公開前確認":true,"公式分野":"消防関係法令","形式":"4択","id":"koron-0003","問題":"次のうち、特定防火対象物に該当しないものはどれか。","選択肢A":"飲食店","選択肢B":"映画館","選択肢C":"テレビスタジオ","選択肢D":"幼稚園","正解":"C","解説":"テレビスタジオは非特定防火対象物です。飲食店、映画館、幼稚園は特定防火対象物に該当します。","間違えやすい理由":"映画スタジオ・テレビスタジオと映画館は分類が異なります。名称の似た施設を区別します。","音声用文章":"テレビスタジオは非特定防火対象物です。映画館は特定防火対象物なので区別します。","詳細タグ":["防火対象物","特定防火対象物","スタジオ"],"学習タグ":["間違いやすい"],"頻出度":4,"根拠":"公論出版「消防設備士 第6類 501問」令和8年版 p.19 問3・p.20 正解解説（IMG_0746・IMG_0747）"},{"資格":"消防設備士乙6類","教材":"公論出版","分野":"消防関係法令（共通）","難易度":"標準","販売対象":true,"公開前確認":true,"公式分野":"消防関係法令","形式":"4択","id":"koron-0004","問題":"次の組合せのうち、すべて特定防火対象物に該当するものはどれか。","選択肢A":"劇場・小学校・幼稚園","選択肢B":"公会堂・飲食店・図書館","選択肢C":"百貨店・ナイトクラブ・工場","選択肢D":"旅館・病院・ダンスホール","正解":"D","解説":"旅館、病院、ダンスホールはいずれも特定防火対象物です。他の組合せには、小学校、図書館、工場などの非特定防火対象物が含まれます。","間違えやすい理由":"3施設のうち1つだけ非特定を混ぜる形式です。一つずつ分類を確認します。","音声用文章":"旅館、病院、ダンスホールは、すべて特定防火対象物です。","詳細タグ":["防火対象物","特定防火対象物","組合せ"],"学習タグ":["頻出","間違いやすい"],"頻出度":4,"根拠":"公論出版「消防設備士 第6類 501問」令和8年版 p.19 問4・p.20 正解解説（IMG_0746・IMG_0747）"},{"資格":"消防設備士乙6類","教材":"公論出版","分野":"消防関係法令（共通）","難易度":"標準","販売対象":true,"公開前確認":true,"公式分野":"消防関係法令","形式":"4択","id":"koron-0005","問題":"次の組合せのうち、いずれも特定防火対象物に該当しないものはどれか。","選択肢A":"飲食店・料理店","選択肢B":"公会堂・集会場","選択肢C":"老人デイサービスセンター・更生施設","選択肢D":"図書館・美術館","正解":"D","解説":"図書館と美術館はいずれも非特定防火対象物です。ほかの組合せは特定防火対象物に該当します。","間違えやすい理由":"文化施設を一括して特定と考えず、図書館・博物館・美術館は非特定として整理します。","音声用文章":"図書館と美術館は、どちらも非特定防火対象物です。","詳細タグ":["防火対象物","非特定防火対象物","文化施設"],"学習タグ":["間違いやすい"],"頻出度":4,"根拠":"公論出版「消防設備士 第6類 501問」令和8年版 p.19 問5・p.20 正解解説（IMG_0746・IMG_0747）"},{"資格":"消防設備士乙6類","教材":"公論出版","分野":"消防関係法令（共通）","難易度":"標準","販売対象":true,"公開前確認":true,"公式分野":"消防関係法令","形式":"4択","id":"koron-0006","問題":"次のうち、特定防火対象物に該当するものはどれか。","選択肢A":"図書館と事務所からなる高層ビル","選択肢B":"蒸気浴場・熱気浴場などの公衆浴場","選択肢C":"テレビスタジオを併設する映画スタジオ","選択肢D":"冷凍倉庫を含む作業場","正解":"B","解説":"蒸気浴場・熱気浴場などの公衆浴場は特定防火対象物です。ほかの選択肢は非特定防火対象物の用途で構成されています。","間違えやすい理由":"一般の公衆浴場と、蒸気浴場・熱気浴場などでは分類が異なる点に注意します。","音声用文章":"蒸気浴場、熱気浴場などの公衆浴場は、特定防火対象物です。","詳細タグ":["防火対象物","特定防火対象物","公衆浴場"],"学習タグ":["頻出","間違いやすい"],"頻出度":4,"根拠":"公論出版「消防設備士 第6類 501問」令和8年版 p.19 問6・p.20 正解解説（IMG_0746・IMG_0747）"},{"資格":"消防設備士乙6類","教材":"公論出版","分野":"消防関係法令（第6類）","難易度":"標準","販売対象":true,"公開前確認":true,"公式分野":"消防関係法令","形式":"4択","id":"koron-0007","問題":"大型消火器を設置する場合の配置基準として、正しいものはどれか。","選択肢A":"ボイラー室の各部分から水平距離20m以下","選択肢B":"電気設備の各部分から歩行距離20m以下","選択肢C":"指定可燃物の貯蔵・取扱場所の各部分から歩行距離30m以下","選択肢D":"少量危険物の貯蔵・取扱場所の各部分から水平距離30m以下","正解":"C","解説":"大型消火器は、防火対象物の階ごとに、指定可燃物を貯蔵・取り扱う場所の各部分から一の大型消火器までの歩行距離が30m以下となるよう設置します。","間違えやすい理由":"水平距離ではなく歩行距離で判断し、基準は30m以下です。","音声用文章":"大型消火器は、指定可燃物の各部分から歩行距離30メートル以下です。","根拠":"公論出版 令和8年版 p.126 問1・p.128 正答（IMG_0857・IMG_0859）","頻出度":4,"詳細タグ":["大型消火器","設置基準"],"学習タグ":["頻出","間違いやすい"]},{"資格":"消防設備士乙6類","教材":"公論出版","分野":"消防関係法令（第6類）","難易度":"標準","販売対象":true,"公開前確認":true,"公式分野":"消防関係法令","形式":"4択","id":"koron-0008","問題":"指定可燃物を貯蔵する場所に大型消火器を設置するとき、一の大型消火器までの距離として正しいものはどれか。","選択肢A":"歩行距離10m以下","選択肢B":"歩行距離20m以下","選択肢C":"歩行距離30m以下","選択肢D":"歩行距離40m以下","正解":"C","解説":"指定可燃物の貯蔵・取扱場所では、一の大型消火器に至る歩行距離を30m以下とします。","間違えやすい理由":"通常の消火器具の20m以下と、大型消火器の30m以下を混同しやすい点に注意します。","音声用文章":"通常消火器は20メートル、大型消火器は30メートルの歩行距離です。","根拠":"公論出版 令和8年版 p.126 問2・p.128 正答（IMG_0857・IMG_0859）","頻出度":5,"詳細タグ":["大型消火器","設置基準"],"学習タグ":["頻出","間違いやすい"]},{"資格":"消防設備士乙6類","教材":"公論出版","分野":"消防関係法令（第6類）","難易度":"標準","販売対象":true,"公開前確認":true,"公式分野":"消防関係法令","形式":"4択","id":"koron-0009","問題":"指定可燃物に対する大型消火器の設置条件の組合せとして、正しいものはどれか。","選択肢A":"指定数量の500倍以上・階ごと・歩行距離30m以下","選択肢B":"指定数量の500倍以上・用途ごと・歩行距離50m以下","選択肢C":"指定数量の300倍以上・階ごと・歩行距離50m以下","選択肢D":"指定数量の300倍以上・用途ごと・歩行距離30m以下","正解":"A","解説":"指定可燃物を指定数量の500倍以上貯蔵・取り扱う場合、種類ごとに適応する大型消火器を階ごとに、歩行距離30m以下となるよう設置します。","間違えやすい理由":"500倍・階ごと・30m以下の3点を一組で覚えます。","音声用文章":"大型消火器は、指定数量500倍以上、階ごと、歩行距離30メートル以下です。","根拠":"公論出版 令和8年版 p.126 問3・p.128 正答（IMG_0857・IMG_0859）","頻出度":5,"詳細タグ":["大型消火器","設置基準"],"学習タグ":["頻出","間違いやすい"]},{"資格":"消防設備士乙6類","教材":"公論出版","分野":"消防関係法令（第6類）","難易度":"標準","販売対象":true,"公開前確認":true,"公式分野":"消防関係法令","形式":"4択","id":"koron-0010","問題":"指定可燃物の場所に必要な消火器具について、正しい組合せはどれか。","選択肢A":"指定数量500倍以上・大型消火器・階ごと・大型消火器まで歩行距離30m以下","選択肢B":"指定数量100倍以上・大型消火器・全階・大型消火器まで水平距離30m以下","選択肢C":"指定数量10倍以上・大型消火器以外・階ごと・通常消火器まで歩行距離20m以下","選択肢D":"指定数量2倍以上・大型消火器以外・部分ごと・通常消火器まで水平距離20m以下","正解":"A","解説":"大型消火器については、指定数量500倍以上、階ごと、大型消火器まで歩行距離30m以下の組合せが正しいものです。","間違えやすい理由":"通常消火器の付加設置条件と大型消火器の条件を混ぜないようにします。","音声用文章":"500倍以上なら大型消火器を階ごとに置き、歩行距離30メートル以下とします。","根拠":"公論出版 令和8年版 p.127 問4・p.128 正答（IMG_0858・IMG_0859）","頻出度":4,"詳細タグ":["大型消火器","設置基準"],"学習タグ":["頻出","間違いやすい"]},{"資格":"消防設備士乙6類","教材":"公論出版","分野":"消防関係法令（第6類）","難易度":"標準","販売対象":true,"公開前確認":true,"公式分野":"消防関係法令","形式":"4択","id":"koron-0011","問題":"大型消火器を設置した有効範囲内で、同じ適応性を持つ消火器具の能力単位を減少できる上限はどれか。","選択肢A":"合計数の1/5まで","選択肢B":"合計数の1/4まで","選択肢C":"合計数の1/3まで","選択肢D":"合計数の1/2まで","正解":"D","解説":"大型消火器を基準に従って設置した場合、その有効範囲内では同じ適応性を持つ消火器具の能力単位を合計数の2分の1まで減少できます。","間違えやすい理由":"他の消火設備による3分の1減少と混同しやすいところです。大型消火器は2分の1です。","音声用文章":"大型消火器による能力単位の減少は、2分の1までです。","根拠":"公論出版 令和8年版 p.127 問5・p.128 正答（IMG_0858・IMG_0859）","頻出度":4,"詳細タグ":["大型消火器","設置基準"],"学習タグ":["頻出","間違いやすい"]},{"資格":"消防設備士乙6類","教材":"公論出版","分野":"消防関係法令（第6類）","難易度":"標準","販売対象":true,"公開前確認":true,"公式分野":"消防関係法令","形式":"4択","id":"koron-0012","問題":"技術基準に従って設置されていても、その有効範囲内で大型消火器を省略できる消火設備に該当しないものはどれか。","選択肢A":"屋内消火栓設備","選択肢B":"屋外消火栓設備","選択肢C":"スプリンクラー設備","選択肢D":"不活性ガス消火設備","正解":"B","解説":"屋外消火栓設備は、大型消火器を省略できる消火設備の対象に含まれません。屋内消火栓、スプリンクラー、不活性ガスなどは対象です。","間違えやすい理由":"屋内と屋外の消火栓設備を取り違えないようにします。","音声用文章":"大型消火器の省略対象に、屋外消火栓設備は含まれません。","根拠":"公論出版 令和8年版 p.127 問6・p.128 正答（IMG_0858・IMG_0859）","頻出度":4,"詳細タグ":["大型消火器","設置基準"],"学習タグ":["頻出","間違いやすい"]}],"introQuestions":[],"releases":{"releases":[{"version":"0.5.0","date":"2026-08-22","newFeatures":["Claude原型UIとGPT整理UIの比較切替","公論出版 第2章・大型消火器の照合済み6問","大型消火器の○×4問・重要ポイント6件"],"improvements":["問題データを共通化しUIだけを比較可能にした"],"bugFixes":[],"knownIssues":["公論出版は照合済み範囲のみ先行収録","法令問題は配布前に現行公的資料と照合が必要"],"next":["実際に両UIを使い、採用UIを決定","公論出版の残り問題を順次照合"]},{"version":"0.4.0","date":"2026-08-22","newFeatures":["公論出版の確認済み4択6問を追加","公論出版の○×一問一答6問を追加","教材別（ユーキャン／公論出版）・全教材ランダムに対応","公論出版の「ここだけ覚える」6件を追加"],"improvements":["問題・正答・解説写真の対応を出典情報に記録","未確認ページを推測で登録しない運用を明示"],"bugFixes":[],"knownIssues":["公論出版はp.19〜20の確認済み6問のみ先行収録","法令問題は配布前に現行の公的資料との照合が必要","Claude側データは未統合"],"next":["公論出版の後続ページを問題・解答単位で照合","Claude側の全章一問一答・第4章・模擬・実技を統合","公開用の文章・画像へ差し替え"]},{"version":"0.3.0","date":"2026-08-21","newFeatures":["○×一問一答15問（○・×・わからない）","回答後に理由・ひっかけ注意・ここだけ覚えるを表示","教材選択（ユーキャン）","本当の一問一答（答えを見る方式）","4択・複数選択・鑑別実技の専用入口","ここだけ覚える74件","聞き流しへの重要ポイント連携"],"improvements":["従来の一問一答を「暗記カード」へ改称","既存71問を教材・形式別に整理","複数選択の見本3問を追加"],"bugFixes":["一問一答が4択として表示されていた問題を分離"],"knownIssues":["教材写真の問題ごとの対応付けは今後実施","法令・規格の問題は配布前に現行公的資料との照合が必要"],"next":["Claude側一問一答の完全統合","公論出版など別教材の追加","公開用画像への差し替え管理"]}]},"keyPoints":[{"id":"kp-0001","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"計算のコツ","タイトル":"力の3要素","本文":"力は、大きさ、方向、作用点の3つの要素で表されます。これを力の3要素と言います。","補足":"力のモーメント（回転力）と混同しやすいが、モーメントは力の3要素とは別の概念で、力が回転軸を回転させようとする働きを表す。","関連問題":"shobo6-0001","出典":"参考書 第1章 Lesson1「力について(1)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0002","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"計算のコツ","タイトル":"力の合成","本文":"同一直線上にない2つの力を合成するときは、2力を2辺とする平行四辺形を書いて、その対角線が合力になります。","補足":"2力が同一直線上かつ同じ向きの場合は単純な足し算（B）でよいが、方向が異なる場合は平行四辺形による作図が必要になる点を混同しやすい。","関連問題":"shobo6-0002","出典":"参考書 第1章 Lesson1「力について(1)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0003","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"計算のコツ","タイトル":"力のつり合い","本文":"複数の力がつり合っている状態とは、それらの力を合成した合力の大きさがゼロになっている状態のことです。","補足":"「つり合う」という言葉から力の大きさが等しいことをイメージしやすいが、実際には合力がゼロになることが条件であり、大きさが異なる複数の力でもつり合いは成立する。","関連問題":"shobo6-0003","出典":"参考書 第1章 Lesson1「力について(1)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0004","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"計算のコツ","タイトル":"力のモーメント","本文":"力のモーメントは、力の大きさと、回転軸から作用点までの距離の積で求められます。式で表すと、M イコール エフ かける エル です。","補足":"力のモーメントを求める公式M=F×lを、足し算（F+l）と勘違いしたり、単位をN・mではなくNやmだけで答えてしまう間違いが多い。","関連問題":"shobo6-0004","出典":"参考書 第1章 Lesson2「力について(2)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0005","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"計算のコツ","タイトル":"力のモーメントのつり合い","本文":"力のモーメントがつり合っている状態とは、右回りのモーメントの合計と、左回りのモーメントの合計が等しくなっている状態のことです。","補足":"力そのものの大きさが等しいと考えがちだが、モーメントは力×距離で決まるため、力が小さくても腕（距離）が長ければ大きなモーメントになり、つり合いが成立する場合がある。","関連問題":"shobo6-0005","出典":"参考書 第1章 Lesson2「力について(2)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0006","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"計算のコツ","タイトル":"計算問題","本文":"仕事は、力の大きさと、力の方向に物体が移動した距離の積で表されます。単位はジュールです。","補足":"仕事の単位ジュール（J）と、仕事率の単位ワット（W）を混同しやすい。仕事率は仕事を時間で割った値であり、単純な仕事の計算とは異なる。","関連問題":"shobo6-0006","出典":"参考書 第1章 Lesson3「仕事と摩擦」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0007","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"計算のコツ","タイトル":"計算問題","本文":"仕事率は、仕事の大きさを、かかった時間で割ることで求められます。単位はワットです。","補足":"仕事率を求める際に、時間で割る計算を掛け算と間違えたり、仕事(J)と仕事率(W)の違いを理解せずそのまま800をそのまま答えとしてしまう間違いが多い。","関連問題":"shobo6-0007","出典":"参考書 第1章 Lesson3「仕事と摩擦」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0008","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"ひっかけ注意","タイトル":"機械に関する基礎的知識","本文":"最大摩擦力は、摩擦係数と、物体の重量にあたる垂直抗力との積で求められます。接触面積の大きさは関係ありません。","補足":"接触面積が大きいほど摩擦力も大きくなると考えがちだが、実際には接触面積の大小は最大摩擦力に直接影響しない。摩擦係数は接触面の材質や状態によって決まる。","関連問題":"shobo6-0008","出典":"参考書 第1章 Lesson3「仕事と摩擦」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0009","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"計算のコツ","タイトル":"計算問題","本文":"分速600メートルを秒速に直すには、600を60で割ります。答えは秒速10メートルです。","補足":"分速から秒速に変換する際、60をかけるべきか割るべきか迷いやすい。時間の単位が小さくなる（分→秒）ので、同じ距離でも1秒あたりの値は小さくなる、つまり60で割る点に注意する。","関連問題":"shobo6-0009","出典":"参考書 第1章 Lesson4「物体の運動」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0010","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"ひっかけ注意","タイトル":"自由落下","本文":"自由落下運動は、重力加速度によって一定の割合で加速し続ける、等加速度直線運動です。","補足":"質量が大きいほど速く落下すると誤解しやすいが、空気抵抗を無視した自由落下では、質量に関係なくすべての物体が同じ加速度で落下する。","関連問題":"shobo6-0010","出典":"参考書 第1章 Lesson4「物体の運動」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0011","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"ここだけ覚える","タイトル":"慣性","本文":"外力が加わらない、またはつり合っている場合、静止している物体は静止を続け、運動している物体は等速直線運動を続けます。これを運動の法則、慣性の法則と言います。","補足":"現実には摩擦力などが働くため物体は自然に減速するが、これは摩擦という外力が働いているためであり、外力がない理想状態では等速直線運動が続く点を混同しやすい。","関連問題":"shobo6-0011","出典":"参考書 第1章 Lesson4「物体の運動」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0012","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"計算のコツ","タイトル":"パスカルの原理","本文":"パスカルの原理とは、密閉された容器内の液体や気体の一部に圧力を加えると、その圧力は容器内のどの部分にも均等に伝わるという原理です。","補足":"圧力を加えた点に近いほど強く伝わると考えがちだが、パスカルの原理では液体・気体内のどの部分にも均等な大きさで圧力が伝わる点がポイントである。","関連問題":"shobo6-0012","出典":"参考書 第1章 Lesson5「圧力と液体・気体」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0013","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"計算のコツ","タイトル":"ボイルの法則","本文":"ボイルの法則とは、温度が一定のとき、気体の体積は圧力に反比例するという法則です。","補足":"シャルルの法則（体積は絶対温度に比例）と混同しやすい。ボイルの法則は圧力と体積の反比例関係、シャルルの法則は温度と体積の比例関係を示す点を区別する必要がある。","関連問題":"shobo6-0013","出典":"参考書 第1章 Lesson5「圧力と液体・気体」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0014","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"計算のコツ","タイトル":"シャルルの法則","本文":"シャルルの法則とは、圧力が一定のとき、気体の体積は絶対温度に比例するという法則です。","補足":"ボイルの法則（圧力と体積は反比例）と混同しやすい。シャルルの法則は温度と体積の比例関係を示すという違いを整理して覚える必要がある。","関連問題":"shobo6-0014","出典":"参考書 第1章 Lesson5「圧力と液体・気体」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0015","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"計算のコツ","タイトル":"ゲージ圧","本文":"絶対圧は、ゲージ圧に大気圧を加えた値です。ゲージ圧は、大気圧を基準にゼロとして測った圧力のことです。","補足":"圧力計が示す値（ゲージ圧）がそのまま絶対圧だと誤解しやすいが、一般的な圧力計は大気圧を基準としたゲージ圧を表示しており、絶対圧を求めるには大気圧を加算する必要がある。","関連問題":"shobo6-0015","出典":"参考書 第1章 Lesson5「圧力と液体・気体」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0016","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"ひっかけ注意","タイトル":"展性・延性","本文":"展性とは、金属を打ち延ばして、薄い板のように広げることができる性質のことです。","補足":"「延性」（引き伸ばして線にできる性質）と「展性」（打ち延ばして板にできる性質）は名前も意味も似ているため混同しやすい。","関連問題":"shobo6-0016","出典":"参考書 第1章 Lesson7「機械材料(2)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0017","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"ひっかけ注意","タイトル":"合金","本文":"黄銅、別名真鍮は、銅と亜鉛の合金です。青銅は、銅とすずの合金である点と区別して覚えましょう。","補足":"黄銅（銅+亜鉛）と青銅（銅+すず）は名前が似ており、組成の元素を混同しやすい。「黄銅は亜鉛、青銅はすず」と対で覚えるとよい。","関連問題":"shobo6-0017","出典":"参考書 第1章 Lesson7「機械材料(2)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0018","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"ここだけ覚える","タイトル":"ステンレス鋼","本文":"ステンレス鋼は、低炭素鋼にクロムとニッケルを添加した合金で、さびにくい性質を持っています。","補足":"「ステンレス」という名前から鉄を含まない特殊な金属だと誤解しやすいが、実際は鉄鋼材料の一種であり、クロムやニッケルの添加によってさびにくくした合金である。","関連問題":"shobo6-0018","出典":"参考書 第1章 Lesson7「機械材料(2)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0019","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"計算のコツ","タイトル":"計算問題","本文":"応力は、荷重を、物体の断面積で割ることで求められます。単位はメガパスカル、またはニュートン毎平方ミリメートルです。","補足":"断面積の単位をmm²で計算する点や、応力の単位N/mm²がMPaと同じ値になる点を忘れると計算ミスにつながる。断面積を求める掛け算を忘れて荷重をそのまま長さで割ってしまう間違いも多い。","関連問題":"shobo6-0019","出典":"参考書 第1章 Lesson8「荷重と応力(1)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0020","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"計算のコツ","タイトル":"弾性限度","本文":"弾性限度とは、荷重を取り除いたとき、伸びていた部分が元の長さに戻る限界点のことです。","補足":"「比例限度」（応力とひずみが比例関係にある限界点）と「弾性限度」（元の長さに戻る限界点）は応力ひずみ図上で近い位置にあり、意味の違いを混同しやすい。","関連問題":"shobo6-0020","出典":"参考書 第1章 Lesson8「荷重と応力(2)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0021","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"計算のコツ","タイトル":"許容応力","本文":"許容応力とは、材料を安全に使用することのできる、最大の応力のことです。","補足":"「極限強さ」（材料が破断する応力）と「許容応力」（安全に使用できる応力）を同じものと誤解しやすいが、許容応力は極限強さより小さく、安全率によって余裕を持たせた値である。","関連問題":"shobo6-0021","出典":"参考書 第1章 Lesson8「荷重と応力(2)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0022","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"計算のコツ","タイトル":"荷重の種類","本文":"衝撃荷重とは、ハンマーで材料を打つときのように、急激に加わる荷重のことです。","補足":"静荷重・衝撃荷重・交番荷重・繰返し荷重はいずれも荷重の分類名であり、それぞれの定義（時間的変化の有無、急激さ、向きの変化）を正確に区別する必要がある。","関連問題":"shobo6-0022","出典":"参考書 第1章 Lesson8「荷重と応力(1)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0023","教材":"ユーキャン","分野":"消防関係法令（共通）","種別":"ひっかけ注意","タイトル":"特定防火対象物","本文":"特定防火対象物とは、百貨店やホテルのように、不特定多数の者が出入りする、または避難が困難な者が入所する用途を含む防火対象物のことです。","補足":"「防火対象物」と「特定防火対象物」の違いを混同しやすい。防火対象物は消防法上の建築物等全般を指す広い概念で、特定防火対象物はそのうち不特定多数が出入りする等の用途に限定した分類である。","関連問題":"shobo6-0023","出典":"参考書 第2章 Lesson1「消防法令上の用語」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0024","教材":"ユーキャン","分野":"消防関係法令（共通）","種別":"ひっかけ注意","タイトル":"無窓階","本文":"無窓階とは、採光上、排煙上、または消火活動上有効な開口部を有しない階のことです。","補足":"文字通り「窓が無い階」と解釈しがちだが、実際には窓があっても、採光・排煙・消火活動上有効に機能する開口部でなければ無窓階に該当する場合がある。","関連問題":"shobo6-0024","出典":"参考書 第2章 Lesson1「消防法令上の用語」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0025","教材":"ユーキャン","分野":"消防関係法令（共通）","種別":"ここだけ覚える","タイトル":"立入検査","本文":"消防職員による立入検査は、関係者の承諾を得ることなく行うことができます。","補足":"一般の立入検査と、個人の住居への立入りの取り扱いの違いを混同しやすい。一般の防火対象物への立入検査には承諾は不要だが、個人の住居は保護の程度が異なる。","関連問題":"shobo6-0025","出典":"参考書 第2章 Lesson2「消防の組織と火災予防」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0026","教材":"ユーキャン","分野":"消防関係法令（共通）","種別":"ここだけ覚える","タイトル":"統括防火管理者","本文":"統括防火管理者は、管理権原が複数に分かれている高層建築物や地下街などで、防火対象物全体の防火管理を行うために選任されます。","補足":"防火管理者（各管理権原者ごとに選任）と統括防火管理者（管理権原が分かれた建物全体をまとめる）の役割の違いを混同しやすい。","関連問題":"shobo6-0026","出典":"参考書 第2章 Lesson3「防火管理者と統括防火管理者」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0027","教材":"ユーキャン","分野":"消防関係法令（共通）","種別":"ひっかけ注意","タイトル":"消防関係法令（共通）","本文":"防炎規制の対象となるのは、高層建築物や特定防火対象物などで使用されるカーテン、じゅうたん等、工事用シートなどです。一般家庭の衣類は対象ではありません。","補足":"防炎規制はすべてのカーテンやカーペットに一律に適用されると誤解しやすいが、実際は使用場所（高層建築物、特定防火対象物等）が限定されている点に注意が必要である。","関連問題":"shobo6-0027","出典":"参考書 第2章 Lesson4「防火対象物の点検、防炎規制」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0028","教材":"ユーキャン","分野":"消防関係法令（共通）","種別":"ここだけ覚える","タイトル":"指定数量","本文":"指定数量とは、危険物の種類ごとに、その危険性を考慮して政令で定められた数量のことです。","補足":"指定数量がすべての危険物で共通の数値だと誤解しやすいが、実際には危険物の種類・品名ごとに異なる数値が定められている。","関連問題":"shobo6-0028","出典":"参考書 第2章 Lesson5「危険物規制」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0029","教材":"ユーキャン","分野":"消防関係法令（共通）","種別":"ひっかけ注意","タイトル":"設置維持義務","本文":"消防用設備等の設置と維持の義務を負うのは、防火対象物の関係者、つまり所有者、管理者または占有者です。","補足":"実際に工事を行う消防設備士が設置義務を負っていると誤解しやすいが、義務を負うのはあくまで防火対象物の関係者（所有者・管理者・占有者）である。","関連問題":"shobo6-0029","出典":"参考書 第2章 Lesson6「消防用設備等に関する規定(1)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0030","教材":"ユーキャン","分野":"消防関係法令（共通）","種別":"計算のコツ","タイトル":"設置単位","本文":"消防用設備等の設置単位は、特段の規定がない限り、1棟の建築物を1つの防火対象物とみなして適用します。","補足":"同一敷地内にある複数の建物をまとめて1つの防火対象物とみなすと誤解しやすいが、原則はあくまで「1棟＝1防火対象物」であり、敷地単位ではない。","関連問題":"shobo6-0030","出典":"参考書 第2章 Lesson7「消防用設備等に関する規定(2)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0031","教材":"ユーキャン","分野":"消防関係法令（共通）","種別":"ひっかけ注意","タイトル":"着工届","本文":"消防設備士は、消防用設備等の工事に着手する日の10日前までに、着工届を消防長または消防署長に提出しなければなりません。","補足":"「設置届」（工事完了後に関係者が提出）と「着工届」（工事着手前に消防設備士が提出）を混同しやすい。届出者・提出時期・提出内容がそれぞれ異なる点を整理して覚える必要がある。","関連問題":"shobo6-0031","出典":"参考書 第2章 Lesson8「消防用設備等に関する規定(3)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0032","教材":"ユーキャン","分野":"消防関係法令（共通）","種別":"ひっかけ注意","タイトル":"点検","本文":"消防用設備等の点検は、機器点検が6か月に1回、総合点検が1年に1回行われます。","補足":"機器点検と総合点検の頻度を逆に覚えてしまう間違いが多い。「機器（きき）は半年」「総合は1年」のように語呂で整理するとよい。","関連問題":"shobo6-0032","出典":"参考書 第2章 Lesson8「消防用設備等に関する規定(3)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0033","教材":"ユーキャン","分野":"消防関係法令（共通）","種別":"ひっかけ注意","タイトル":"型式承認","本文":"型式承認は総務大臣が行い、型式適合検定は日本消防検定協会等が行います。","補足":"型式承認（型式そのものの承認、総務大臣が行う）と型式適合検定（個々の製品が承認された型式に適合するかの検定、日本消防検定協会等が行う）は、対象と実施主体の両方が異なる点を混同しやすい。","関連問題":"shobo6-0033","出典":"参考書 第2章 Lesson9「消防用機械器具等の検定」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0034","教材":"ユーキャン","分野":"消防関係法令（共通）","種別":"ここだけ覚える","タイトル":"甲種","本文":"甲種消防設備士は、消防用設備等の工事と整備の両方を行うことができます。乙種消防設備士は、整備のみを行うことができます。","補足":"甲種・乙種の違いを「対象設備の種類の違い」とだけ覚えてしまい、「工事ができるかどうか」という業務範囲の違いを見落としやすい。","関連問題":"shobo6-0034","出典":"参考書 第2章 Lesson10「消防設備士制度」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0035","教材":"ユーキャン","分野":"消防関係法令（共通）","種別":"ひっかけ注意","タイトル":"講習","本文":"消防設備士は、免状交付後最初の4月1日から2年以内に講習を受け、その後は5年以内ごとに講習を受ける必要があります。","補足":"免状の「書換え」（本籍地・氏名等の変更、居住地・勤務地の都道府県知事に申請）と「講習」（業務従事者に義務付けられた知識・技術の維持のための受講）を混同しやすい。目的も期限の起算点も異なる。","関連問題":"shobo6-0035","出典":"参考書 第2章 Lesson10「消防設備士制度」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0036","教材":"ユーキャン","分野":"消防関係法令（第6類）","種別":"ひっかけ注意","タイトル":"地階・無窓階","本文":"地階、無窓階、または3階以上の階については、延べ面積にかかわらず、その階の床面積が50平方メートル以上であれば消火器具の設置が義務づけられます。","補足":"防火対象物全体で見る通常の延べ面積基準（150㎡や300㎡）と、特定の階（地階・無窓階・3階以上）に個別に適用される床面積50㎡以上の基準を混同しやすい。","関連問題":"shobo6-0036","出典":"参考書 第3章 Lesson1「消火器具の設置義務(1)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0037","教材":"ユーキャン","分野":"消防関係法令（第6類）","種別":"計算のコツ","タイトル":"算定基準面積","本文":"主要構造部を耐火構造とし、内装仕上げを難燃材料とした防火対象物は、算定基準面積の数値を2倍にすることができます。","補足":"「耐火構造にすると必要な消火器の数が減る」という結論は合っているが、算定基準面積を「2倍にする」のか「半分にする」のかを逆に覚えてしまう間違いが多い。基準面積が大きくなる＝必要な能力単位が少なくなる、という関係を理解する必要がある。","関連問題":"shobo6-0037","出典":"参考書 第3章 Lesson2「消火器具の設置義務(2)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0038","教材":"ユーキャン","分野":"消防関係法令（第6類）","種別":"ここだけ覚える","タイトル":"歩行距離","本文":"消火器具は、大型消火器を除き、防火対象物の各部分からの歩行距離が20メートル以下となるように配置します。大型消火器の場合は30メートル以下です。","補足":"大型消火器の基準（歩行距離30m以下）と、通常の消火器具の基準（歩行距離20m以下）を混同しやすい。「大型は大きい数字（30m）」と関連づけて覚えるとよい。","関連問題":"shobo6-0038","出典":"参考書 第3章 Lesson3「消火器具の設置基準(1)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0039","教材":"ユーキャン","分野":"消防関係法令（第6類）","種別":"ここだけ覚える","タイトル":"設置高さ","本文":"消火器具は、床面からの高さ1.5メートル以下の箇所に設置しなければなりません。","補足":"他の設備・器具の高さ基準（例：無窓階の判定基準や別の設備の設置高さ）と数値を混同しやすい。消火器具は「1.5m以下」と正確に覚える必要がある。","関連問題":"shobo6-0039","出典":"参考書 第3章 Lesson3「消火器具の設置基準(1)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0040","教材":"ユーキャン","分野":"消防関係法令（第6類）","種別":"ひっかけ注意","タイトル":"地下街等","本文":"換気が不十分な地下街等の居室には、二酸化炭素を放射する消火器や、一部を除くハロゲン化物を放射する消火器は、酸欠や中毒のおそれがあるため設置できません。","補足":"「一部を除く」とされているハロゲン化物（ハロン1301を放射するものは設置できる）の例外規定を見落とし、すべてのハロゲン化物消火器が一律に設置禁止だと誤解しやすい。","関連問題":"shobo6-0040","出典":"参考書 第3章 Lesson4「消火器具の設置基準(2)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0041","教材":"ユーキャン","分野":"消防関係法令（第6類）","種別":"ひっかけ注意","タイトル":"電気火災","本文":"電気設備の火災に対して、水や強化液を棒状に放射する消火器は適応しませんが、霧状に放射するものは適応します。","補足":"「水は電気火災に使えない」と一律に覚えてしまいがちだが、正確には放射方法（棒状か霧状か）によって適応性が異なる点がポイントである。","関連問題":"shobo6-0041","出典":"参考書 第3章 Lesson4「消火器具の設置基準(2)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0042","教材":"ユーキャン","分野":"消火器の構造・機能・整備","種別":"ひっかけ注意","タイトル":"抑制消火","本文":"抑制消火とは、酸化反応の連鎖を化学的に抑制することで燃焼を中止させる方法です。","補足":"除去・窒息・冷却の3要素（燃焼の3要素に対応）はイメージしやすいが、「抑制」は化学的な作用であり直感的に理解しにくいため、他の3つと混同したり説明を誤って覚えやすい。","関連問題":"shobo6-0042","出典":"参考書 第4章 Lesson1「消火の理論と消火剤」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0043","教材":"ユーキャン","分野":"消火器の構造・機能・整備","種別":"計算のコツ","タイトル":"蓄圧式","本文":"蓄圧式の消火器は、二酸化炭素消火器とハロン1301消火器を除き、すべてに指示圧力計を取り付ける必要があります。","補足":"加圧式（ガス加圧式）は加圧用ガス容器の圧力によって消火剤を放射する方式で、指示圧力計は取り付けられていない点を混同しやすい。","関連問題":"shobo6-0043","出典":"参考書 第4章 Lesson2「消火器の種類」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0044","教材":"ユーキャン","分野":"消火器の構造・機能・整備","種別":"ひっかけ注意","タイトル":"消火剤の性質","本文":"強化液消火剤は、炭酸カリウム等の濃厚な水溶液で、アルカリ性です。凝固点が低いため、寒冷地でも使用しやすいという特徴があります。","補足":"強化液が酸性だと誤解しやすいが、実際はアルカリ性である。また、凍結しやすいと誤解しやすいが、逆に凝固点を下げる加工がされているため寒冷地に適している。","関連問題":"shobo6-0044","出典":"参考書 第4章 Lesson3「水消火器と強化液消火器」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0045","教材":"ユーキャン","分野":"消火器の構造・機能・整備","種別":"ひっかけ注意","タイトル":"化学泡消火器","本文":"化学泡消火器のA剤の主成分は炭酸水素ナトリウム、B剤の主成分は硫酸アルミニウムです。この2つの化学反応によって二酸化炭素を含む泡が発生します。","補足":"A剤とB剤の成分を逆に覚えやすい。「A剤はアルカリ性の重曹（炭酸水素ナトリウム）」「B剤は硫酸アルミニウム」と、頭文字や性質と関連づけて整理する必要がある。","関連問題":"shobo6-0045","出典":"参考書 第4章 Lesson4「泡消火器」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0046","教材":"ユーキャン","分野":"消火器の構造・機能・整備","種別":"ひっかけ注意","タイトル":"ハロン1301消火器","本文":"二酸化炭素消火器とハロン1301消火器は、どちらも高圧ガス保安法の適用を受け、消火剤自身の圧力によって放射するため、指示圧力計は付いていません。","補足":"他の蓄圧式消火器と同様に指示圧力計が付いていると誤解しやすいが、二酸化炭素消火器とハロン1301消火器は自身の圧力で放射するため、指示圧力計は不要という点が特殊である。","関連問題":"shobo6-0046","出典":"参考書 第4章 Lesson5「二酸化炭素消火器とハロン1301消火器」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0047","教材":"ユーキャン","分野":"消火器の構造・機能・整備","種別":"ひっかけ注意","タイトル":"適応火災","本文":"りん酸アンモニウムを主成分とする粉末消火剤は、A火災、B火災、C火災のすべてに適応します。","補足":"粉末消火剤には主成分によって適応火災が異なるものが複数存在する（りん酸塩系はABC全対応、炭酸水素塩系はBC対応）。この違いを混同しやすい。","関連問題":"shobo6-0047","出典":"参考書 第4章 Lesson6「粉末消火器」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0048","教材":"ユーキャン","分野":"消火器の構造・機能・整備","種別":"計算のコツ","タイトル":"指示圧力計","本文":"指示圧力計の指針が緑色範囲の上限より上がっている、または下限より下がっている場合は、機能点検を行う必要があります。","補足":"外観点検の範囲内で完結する対応（清掃や部品交換）で済むと考えがちだが、圧力の異常は消火器の機能そのものに関わるため、より詳細な機能点検が必要になる点がポイント。","関連問題":"shobo6-0048","出典":"参考書 第4章 Lesson8「外観点検(2)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0049","教材":"ユーキャン","分野":"消火器の構造・機能・整備","種別":"ひっかけ注意","タイトル":"化学泡消火器","本文":"化学泡消火器は、製造年から1年を経過したものについて、全数を対象に機能点検を実施します。","補足":"加圧式消火器（二酸化炭素・ハロゲン化物を除く）の3年、蓄圧式消火器の5年という基準と混同しやすい。化学泡消火器は薬剤の性質上、最も短い1年という点が特徴である。","関連問題":"shobo6-0049","出典":"参考書 第4章 Lesson9「機能点検の概要」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0050","教材":"ユーキャン","分野":"消火器の構造・機能・整備","種別":"ひっかけ注意","タイトル":"抜取り方式","本文":"蓄圧式の粉末消火器で、製造年から10年を超えるものは、抜取り方式ではなく全数を対象として機能点検を行います。","補足":"抜取り方式が使える条件（製造年から10年以内）と使えない条件（10年超は全数点検）を逆に覚えやすい。","関連問題":"shobo6-0050","出典":"参考書 第4章 Lesson9「機能点検の概要」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0051","教材":"ユーキャン","分野":"消火器の構造・機能・整備","種別":"ここだけ覚える","タイトル":"残圧排出","本文":"排圧栓のない蓄圧式消火器は、安全栓を外し、レバーを握って残圧を排出してから分解します。","補足":"排圧栓の有無によって残圧排出の手順が異なる点を混同しやすい。排圧栓がある場合とない場合の手順をそれぞれ正確に区別して覚える必要がある。","関連問題":"shobo6-0051","出典":"参考書 第4章 Lesson10「消火器の分解の手順」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0052","教材":"ユーキャン","分野":"消火器の規格","種別":"計算のコツ","タイトル":"能力単位","本文":"大型消火器は、A火災に適応するものは能力単位10単位以上、B火災に適応するものは20単位以上であることが基準です。","補足":"A火災とB火災の基準数値（10単位・20単位）を逆に覚えやすい。","関連問題":"shobo6-0052","出典":"参考書 第5章 Lesson1「消火器の技術上の規格(1)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0053","教材":"ユーキャン","分野":"消火器の規格","種別":"計算のコツ","タイトル":"大型消火器","本文":"大型の化学泡消火器の薬剤充てん量は、80キログラムではなく、80リットル以上です。単位の違いに注意しましょう。","補足":"液体薬剤の単位（ℓ）と粉末・気体薬剤の単位（kg）を混同しやすい。化学泡消火剤は液体だがℓ表記であることを正確に覚える必要がある。","関連問題":"shobo6-0053","出典":"参考書 第5章 Lesson1「消火器の技術上の規格(1)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0054","教材":"ユーキャン","分野":"消火器の規格","種別":"ひっかけ注意","タイトル":"操作の機構","本文":"手さげ式消火器は、住宅用消火器を除き、すべて1動作で放射を開始できるものでなければなりません。","補足":"手さげ式の1動作と、車載式の3動作以内という基準を混同しやすい。運搬方式によって基準が異なる点に注意が必要である。","関連問題":"shobo6-0054","出典":"参考書 第5章 Lesson2「消火器の技術上の規格(2)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0055","教材":"ユーキャン","分野":"消火器の規格","種別":"ここだけ覚える","タイトル":"放射性能","本文":"消火器の放射時間は、温度20℃において10秒以上であり、消火に有効な放射距離を有する必要があります。","補足":"放射距離について「必ず3m以上」のような固定値があると誤解しやすいが、規格上は「消火に有効な距離」という表現であり、消火器の種類によって実際の放射距離は異なる。","関連問題":"shobo6-0055","出典":"参考書 第5章 Lesson2「消火器の技術上の規格(2)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0056","教材":"ユーキャン","分野":"消火器の規格","種別":"ひっかけ注意","タイトル":"使用温度範囲","本文":"消火器の使用温度範囲は、化学泡消火器を除き、0℃以上40℃以下と定められています。","補足":"化学泡消火器の使用温度範囲（5℃以上40℃以下）と、それ以外の消火器の使用温度範囲（0℃以上40℃以下）の下限温度を混同しやすい。","関連問題":"shobo6-0056","出典":"参考書 第5章 Lesson2「消火器の技術上の規格(2)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0057","教材":"ユーキャン","分野":"消火器の規格","種別":"ここだけ覚える","タイトル":"安全栓","本文":"安全栓のリング部の内径は、2センチメートル以上とされています。","補足":"他の部品（安全弁の口径など）の数値と混同しやすい。安全栓のリング内径は「2cm以上」と正確に覚える必要がある。","関連問題":"shobo6-0057","出典":"参考書 第5章 Lesson3「部品に関する規格(1)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0058","教材":"ユーキャン","分野":"消火器の規格","種別":"計算のコツ","タイトル":"指示圧力計","本文":"指示圧力計の指示圧力範囲は、使用圧力値の上下15パーセント以内とされています。","補足":"「使用圧力範囲（0.7～0.98MPa）」という固定の数値と、「指示圧力範囲の許容誤差（使用圧力値の上下15%以内）」という別の基準を混同しやすい。","関連問題":"shobo6-0058","出典":"参考書 第5章 Lesson4「部品に関する規格(2)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0059","教材":"ユーキャン","分野":"消火器の規格","種別":"ひっかけ注意","タイトル":"塗色","本文":"消火器の外面は、その25パーセント以上を赤色仕上げとしなければなりません。","補足":"消火器＝全面赤色というイメージから、外面全体を赤くする必要があると誤解しやすいが、規格上は「25%以上」という下限が定められているに過ぎない。","関連問題":"shobo6-0059","出典":"参考書 第5章 Lesson5「部品に関する規格(3)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0060","教材":"ユーキャン","分野":"消火器の規格","種別":"ひっかけ注意","タイトル":"絵表示","本文":"適応火災の絵表示は、A火災が白色地、B火災が黄色地、C火災が青色地とされています。","補足":"A火災・B火災・C火災それぞれの地色（白・黄・青）を混同しやすい。「油は黄、電気は青」のように語呂で整理するとよい。","関連問題":"shobo6-0060","出典":"参考書 第5章 Lesson5「部品に関する規格(3)」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0061","教材":"ユーキャン","分野":"消火器の規格","種別":"ひっかけ注意","タイトル":"消火薬剤","本文":"消火薬剤は、著しい毒性または腐食性を有しないものであって、かつ腐食性のあるガスを発生しないものでなければなりません。","補足":"文章の否定表現（「有しない」）を見落とし、逆の意味（「有する」）で覚えてしまう間違いが起こりやすい。","関連問題":"shobo6-0061","出典":"参考書 第5章 Lesson6「消火薬剤に関する規格」確認テストページより作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0062","教材":"ユーキャン","分野":"鑑別等（実技）","種別":"実技ポイント","タイトル":"指示圧力計","本文":"蓄圧式消火器に装着されている指示圧力計は、消火器内部の圧力を示します。","補足":"「圧力計＝薬剤の残量を示す」と誤解しやすいが、指示圧力計はあくまで内部の圧力を示すものであり、薬剤の残量そのものを直接示すものではない。","関連問題":"shobo6-0062","出典":"参考書 実技試験対策「1 消火器本体に関する実技試験対策」問題1・4より作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0063","教材":"ユーキャン","分野":"鑑別等（実技）","種別":"実技ポイント","タイトル":"機械泡消火器","本文":"機械泡消火器のノズルは発泡ノズルと呼ばれます。泡を伝って感電する危険性があるため、電気火災には適応しません。","補足":"泡は油の上に浮いて窒息効果を発揮するイメージが強く、感電のリスクを見落としやすい。泡も水分を含む以上、電気を通す媒体になり得る点がポイントである。","関連問題":"shobo6-0063","出典":"参考書 実技試験対策「1 消火器本体に関する実技試験対策」問題2より作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0064","教材":"ユーキャン","分野":"鑑別等（実技）","種別":"実技ポイント","タイトル":"二酸化炭素消火器","本文":"二酸化炭素消火器は容器の2分の1以上を緑色に、ハロン1301消火器は容器の2分の1以上をねずみ色に塗色します。","補足":"二酸化炭素とハロン1301の塗色（緑色とねずみ色）を逆に覚えたり、「全体を塗る」と誤解しやすい。","関連問題":"shobo6-0064","出典":"参考書 実技試験対策「1 消火器本体に関する実技試験対策」問題4・5より作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0065","教材":"ユーキャン","分野":"鑑別等（実技）","種別":"実技ポイント","タイトル":"化学泡消火器","本文":"ろ過網は、消火薬剤中のごみなどによって、ホースやノズルが目詰まりすることを防ぐ役割を持っています。","補足":"「ろ過網」という名称から浄水フィルターのようなものとイメージしがちだが、正確には「ホース・ノズルの目詰まり防止」という機能で覚える必要がある。","関連問題":"shobo6-0065","出典":"参考書 実技試験対策「1 消火器本体に関する実技試験対策」問題6より作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0066","教材":"ユーキャン","分野":"鑑別等（実技）","種別":"実技ポイント","タイトル":"安全弁","本文":"安全弁は、容器の内圧が急激に上昇したときに、圧力を排出する役割を持っています。","補足":"「安全栓」（レバーを不用意に握れないようにするピン状の部品）と「安全弁」（内圧上昇時に圧力を逃がす部品）の名称が似ており、役割を混同しやすい。","関連問題":"shobo6-0066","出典":"参考書 実技試験対策「2 消火器の部品等に関する実技試験対策」問題2より作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0067","教材":"ユーキャン","分野":"鑑別等（実技）","種別":"実技ポイント","タイトル":"加圧用ガス容器","本文":"加圧用ガス容器の「TW」という表示は、容器の総質量を示しています。TW285は、総質量285グラムという意味です。","補足":"「TW」がTotal Weight（総質量）の略であることを知らないと、圧力や日数など他の数値だと誤解しやすい。","関連問題":"shobo6-0067","出典":"参考書 実技試験対策「2 消火器の部品等に関する実技試験対策」問題3より作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0068","教材":"ユーキャン","分野":"鑑別等（実技）","種別":"実技ポイント","タイトル":"整備器具","本文":"反射鏡、別名点検鏡は、消火器本体容器の内面の腐食等を目視で確認するための器具です。キャップの開閉作業に使うのはクランプ台です。","補足":"クランプ台（固定）と反射鏡（内部確認）の用途を入れ替えて覚えてしまう間違いが多い。それぞれの器具の見た目と役割をセットで覚える必要がある。","関連問題":"shobo6-0068","出典":"参考書 実技試験対策「3 器具に関する実技試験対策」問題1・2・3より作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0069","教材":"ユーキャン","分野":"鑑別等（実技）","種別":"実技ポイント","タイトル":"分解・再充てん","本文":"消火器を分解して消火薬剤を再充てんする際には、ドライバー、クランプ台、キャップスパナ、プライヤの4つの器具を使用します。","補足":"反射鏡や標準圧力計は点検（内部確認・圧力確認）に使う器具であり、分解・再充てん作業に使う器具（ドライバー等）とは用途が異なる点を区別する必要がある。","関連問題":"shobo6-0069","出典":"参考書 実技試験対策「4 実技試験対策実践編」問題6より作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0070","教材":"ユーキャン","分野":"鑑別等（実技）","種別":"実技ポイント","タイトル":"使用可能温度","本文":"ハロン1301消火器の最低使用可能温度はマイナス30度で、蓄圧式強化液消火器や蓄圧式機械泡消火器のマイナス20度よりも低いです。","補足":"強化液消火器の凝固点が低いことから、強化液消火器が最も低温に強いと誤解しやすいが、実際にはハロン1301消火器の方がさらに低温での使用が可能である。","関連問題":"shobo6-0070","出典":"参考書 実技試験対策「4 実技試験対策実践編」問題4より作成","公開区分":"文章は配布前に再確認"},{"id":"kp-0071","教材":"ユーキャン","分野":"鑑別等（実技）","種別":"実技ポイント","タイトル":"放射性能","本文":"消火器の総質量の減少分から加圧用ガスの質量を引くと、放射された薬剤量が求められます。薬剤量の90パーセント以上が放射されていれば適合です。","補足":"「放射された薬剤量」を求める設問と、「放射されなかった薬剤量」を求める設問を混同しやすい。また、計算の途中で加圧用ガスの質量を引き忘れる間違いも多い。","関連問題":"shobo6-0071","出典":"参考書 実技試験対策「4 実技試験対策実践編」問題7より作成（計算問題）","公開区分":"文章は配布前に再確認"},{"id":"kp-0072","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"計算のコツ","タイトル":"力の3要素","本文":"力の3要素は、大きさ、方向、作用点です。","補足":"力の大きさと質量は関係しますが、同じ単位・同じ量ではありません。","関連問題":"shobo6-multi-0001","出典":"ユーキャン教材をもとに学習用に整理","公開区分":"文章は配布前に再確認"},{"id":"kp-0073","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"計算のコツ","タイトル":"仕事","本文":"仕事は力かける移動距離で、単位はジュールです。","補足":"力を加えても物体が移動しなければ、力学上の仕事は0です。","関連問題":"shobo6-multi-0002","出典":"ユーキャン教材をもとに学習用に整理","公開区分":"文章は配布前に再確認"},{"id":"kp-0074","教材":"ユーキャン","分野":"機械に関する基礎的知識","種別":"計算のコツ","タイトル":"単位","本文":"圧力は力割る面積で、1パスカルは1ニュートン毎平方メートルです。","補足":"同じ力なら、面積が小さいほど圧力は大きくなります。","関連問題":"shobo6-multi-0003","出典":"ユーキャン教材をもとに学習用に整理","公開区分":"文章は配布前に再確認"},{"id":"koron-kp-0001","教材":"公論出版","分野":"消防関係法令（共通）","種別":"ひっかけ注意","タイトル":"学校","本文":"特定防火対象物に該当しないものは、小学校です。幼稚園との違いに注意します。","補足":"幼稚園は特定防火対象物ですが、小学校は非特定です。学校種別をまとめて覚えないことがポイントです。","関連問題":"koron-0001","出典":"公論出版「消防設備士 第6類 501問」令和8年版 p.19 問1・p.20 正解解説（IMG_0746・IMG_0747）","公開区分":"自分用。配布前に現行法令と文章を再確認"},{"id":"koron-kp-0002","教材":"公論出版","分野":"消防関係法令（共通）","種別":"ここだけ覚える","タイトル":"百貨店","本文":"百貨店は特定防火対象物です。小学校、共同住宅、図書館は非特定です。","補足":"人が集まる施設でも、すべてが特定防火対象物になるわけではありません。","関連問題":"koron-0002","出典":"公論出版「消防設備士 第6類 501問」令和8年版 p.19 問2・p.20 正解解説（IMG_0746・IMG_0747）","公開区分":"自分用。配布前に現行法令と文章を再確認"},{"id":"koron-kp-0003","教材":"公論出版","分野":"消防関係法令（共通）","種別":"ひっかけ注意","タイトル":"スタジオ","本文":"テレビスタジオは非特定防火対象物です。映画館は特定防火対象物なので区別します。","補足":"映画スタジオ・テレビスタジオと映画館は分類が異なります。名称の似た施設を区別します。","関連問題":"koron-0003","出典":"公論出版「消防設備士 第6類 501問」令和8年版 p.19 問3・p.20 正解解説（IMG_0746・IMG_0747）","公開区分":"自分用。配布前に現行法令と文章を再確認"},{"id":"koron-kp-0004","教材":"公論出版","分野":"消防関係法令（共通）","種別":"ここだけ覚える","タイトル":"組合せ","本文":"旅館、病院、ダンスホールは、すべて特定防火対象物です。","補足":"3施設のうち1つだけ非特定を混ぜる形式です。一つずつ分類を確認します。","関連問題":"koron-0004","出典":"公論出版「消防設備士 第6類 501問」令和8年版 p.19 問4・p.20 正解解説（IMG_0746・IMG_0747）","公開区分":"自分用。配布前に現行法令と文章を再確認"},{"id":"koron-kp-0005","教材":"公論出版","分野":"消防関係法令（共通）","種別":"ここだけ覚える","タイトル":"文化施設","本文":"図書館と美術館は、どちらも非特定防火対象物です。","補足":"文化施設を一括して特定と考えず、図書館・博物館・美術館は非特定として整理します。","関連問題":"koron-0005","出典":"公論出版「消防設備士 第6類 501問」令和8年版 p.19 問5・p.20 正解解説（IMG_0746・IMG_0747）","公開区分":"自分用。配布前に現行法令と文章を再確認"},{"id":"koron-kp-0006","教材":"公論出版","分野":"消防関係法令（共通）","種別":"ひっかけ注意","タイトル":"公衆浴場","本文":"蒸気浴場、熱気浴場などの公衆浴場は、特定防火対象物です。","補足":"一般の公衆浴場と、蒸気浴場・熱気浴場などでは分類が異なる点に注意します。","関連問題":"koron-0006","出典":"公論出版「消防設備士 第6類 501問」令和8年版 p.19 問6・p.20 正解解説（IMG_0746・IMG_0747）","公開区分":"自分用。配布前に現行法令と文章を再確認"},{"id":"koron-kp-0007","教材":"公論出版","分野":"消防関係法令（第6類）","種別":"ここだけ覚える","タイトル":"大型消火器の距離","本文":"大型消火器は、指定可燃物の各部分から歩行距離30メートル以下です。","補足":"水平距離ではなく歩行距離で判断し、基準は30m以下です。","関連問題":"koron-0007","出典":"公論出版 令和8年版 p.126 問1・p.128 正答（IMG_0857・IMG_0859）","公開区分":"自分用。配布前に現行法令と文章を再確認"},{"id":"koron-kp-0008","教材":"公論出版","分野":"消防関係法令（第6類）","種別":"ひっかけ注意","タイトル":"20mと30m","本文":"通常消火器は20メートル、大型消火器は30メートルの歩行距離です。","補足":"通常の消火器具の20m以下と、大型消火器の30m以下を混同しやすい点に注意します。","関連問題":"koron-0008","出典":"公論出版 令和8年版 p.126 問2・p.128 正答（IMG_0857・IMG_0859）","公開区分":"自分用。配布前に現行法令と文章を再確認"},{"id":"koron-kp-0009","教材":"公論出版","分野":"消防関係法令（第6類）","種別":"ここだけ覚える","タイトル":"500倍・階ごと・30m","本文":"大型消火器は、指定数量500倍以上、階ごと、歩行距離30メートル以下です。","補足":"500倍・階ごと・30m以下の3点を一組で覚えます。","関連問題":"koron-0009","出典":"公論出版 令和8年版 p.126 問3・p.128 正答（IMG_0857・IMG_0859）","公開区分":"自分用。配布前に現行法令と文章を再確認"},{"id":"koron-kp-0010","教材":"公論出版","分野":"消防関係法令（第6類）","種別":"ここだけ覚える","タイトル":"大型消火器の設置条件","本文":"500倍以上なら大型消火器を階ごとに置き、歩行距離30メートル以下とします。","補足":"通常消火器の付加設置条件と大型消火器の条件を混ぜないようにします。","関連問題":"koron-0010","出典":"公論出版 令和8年版 p.127 問4・p.128 正答（IMG_0858・IMG_0859）","公開区分":"自分用。配布前に現行法令と文章を再確認"},{"id":"koron-kp-0011","教材":"公論出版","分野":"消防関係法令（第6類）","種別":"ひっかけ注意","タイトル":"能力単位の減少","本文":"大型消火器による能力単位の減少は、2分の1までです。","補足":"他の消火設備による3分の1減少と混同しやすいところです。大型消火器は2分の1です。","関連問題":"koron-0011","出典":"公論出版 令和8年版 p.127 問5・p.128 正答（IMG_0858・IMG_0859）","公開区分":"自分用。配布前に現行法令と文章を再確認"},{"id":"koron-kp-0012","教材":"公論出版","分野":"消防関係法令（第6類）","種別":"ひっかけ注意","タイトル":"省略対象外","本文":"大型消火器の省略対象に、屋外消火栓設備は含まれません。","補足":"屋内と屋外の消火栓設備を取り違えないようにします。","関連問題":"koron-0012","出典":"公論出版 令和8年版 p.127 問6・p.128 正答（IMG_0858・IMG_0859）","公開区分":"自分用。配布前に現行法令と文章を再確認"}],"trueFalse":[{"id":"tf-0001","教材":"ユーキャン","分野":"機械に関する基礎的知識","問題":"力は、大きさ・方向・作用点の3つの要素で表される。","正解":"○","理由":"力の大きさ、方向、作用点をまとめて力の3要素といいます。","ひっかけ注意":"作用点ではなく、力の向きだけを見て判断しないようにします。","ここだけ覚える":"力の3要素＝大きさ・方向・作用点"},{"id":"tf-0002","教材":"ユーキャン","分野":"機械に関する基礎的知識","問題":"同一直線上にない2つの力の合力は、2力を2辺とする平行四辺形の対角線で表せる。","正解":"○","理由":"方向の異なる2力は、平行四辺形の法則を使って合成します。","ひっかけ注意":"同じ向きで同一直線上にある場合の単純な足し算と区別します。","ここだけ覚える":"方向の異なる2力＝平行四辺形の対角線"},{"id":"tf-0003","教材":"ユーキャン","分野":"機械に関する基礎的知識","問題":"複数の力がつり合うためには、すべての力の大きさが同じでなければならない。","正解":"×","理由":"大きさが同じことではなく、すべてを合成した合力が0になることが条件です。","ひっかけ注意":"『つり合う＝同じ大きさ』とは限りません。","ここだけ覚える":"つり合いの条件＝合力が0"},{"id":"tf-0004","教材":"ユーキャン","分野":"機械に関する基礎的知識","問題":"力のモーメントは、力の大きさと支点から力の作用線までの垂直距離の積で求める。","正解":"○","理由":"力のモーメントは M＝F×l で表します。","ひっかけ注意":"斜めの長さではなく、作用線までの垂直距離を使います。","ここだけ覚える":"モーメント＝力×垂直距離"},{"id":"tf-0005","教材":"ユーキャン","分野":"機械に関する基礎的知識","問題":"物体に力を加えても物体が移動しなければ、力学上の仕事は0である。","正解":"○","理由":"仕事は力と、力の方向への移動距離の積で求めるため、移動距離が0なら仕事も0です。","ひっかけ注意":"疲れたかどうかではなく、物体が移動したかで判断します。","ここだけ覚える":"移動しなければ仕事は0"},{"id":"tf-0006","教材":"ユーキャン","分野":"機械に関する基礎的知識","問題":"仕事の単位である1ジュールは、1ニュートン・メートルに等しい。","正解":"○","理由":"1Nの力で、力の方向へ1m移動させたときの仕事が1Jです。","ひっかけ注意":"仕事率の単位ワットと混同しないようにします。","ここだけ覚える":"1J＝1N・m"},{"id":"tf-0007","教材":"ユーキャン","分野":"機械に関する基礎的知識","問題":"同じ大きさの力が働く場合、面積が大きいほど圧力は大きくなる。","正解":"×","理由":"圧力は力を面積で割るため、同じ力なら面積が小さいほど圧力は大きくなります。","ひっかけ注意":"面積との関係は反比例です。","ここだけ覚える":"同じ力なら、狭いほど高圧"},{"id":"tf-0008","教材":"ユーキャン","分野":"機械に関する基礎的知識","問題":"1パスカルは、1平方メートル当たり1ニュートンの力が働く圧力である。","正解":"○","理由":"圧力の単位はPaで、1Pa＝1N/㎡です。","ひっかけ注意":"N・㎡ではなく、N/㎡です。","ここだけ覚える":"1Pa＝1N/㎡"},{"id":"tf-0009","教材":"ユーキャン","分野":"機械に関する基礎的知識","問題":"加速度の単位はメートル毎秒である。","正解":"×","理由":"メートル毎秒は速度の単位です。加速度はメートル毎秒毎秒、つまりm/s²で表します。","ひっかけ注意":"速度と加速度の単位を区別します。","ここだけ覚える":"速度m/s、加速度m/s²"},{"id":"tf-0010","教材":"ユーキャン","分野":"消火器の構造・機能・整備","問題":"蓄圧式消火器の指示圧力計は、消火器内部の圧力状態を確認するために用いる。","正解":"○","理由":"蓄圧式は常時圧力がかかっているため、指示圧力計で使用可能な圧力範囲を確認します。","ひっかけ注意":"加圧式との外観上の見分け方としても問われます。","ここだけ覚える":"蓄圧式＝指示圧力計を確認"},{"id":"tf-0011","教材":"ユーキャン","分野":"鑑別等（実技）","問題":"消火器の安全弁は、容器内の圧力が異常に上昇したときに圧力を逃がすための部品である。","正解":"○","理由":"異常な圧力上昇による危険を防ぐため、一定以上の圧力を外へ逃がします。","ひっかけ注意":"通常の放射操作に使う弁ではありません。","ここだけ覚える":"安全弁＝異常圧力を逃がす"},{"id":"tf-0012","教材":"ユーキャン","分野":"鑑別等（実技）","問題":"化学泡消火器のろ過網は、ごみなどによるホースやノズルの目詰まりを防ぐ。","正解":"○","理由":"消火薬剤中の異物をろ過し、放射経路の目詰まりを防止します。","ひっかけ注意":"薬剤を混合するための部品ではありません。","ここだけ覚える":"ろ過網＝目詰まり防止"},{"id":"tf-0013","教材":"ユーキャン","分野":"鑑別等（実技）","問題":"機械泡消火器は、電気火災への使用に適している。","正解":"×","理由":"水系の消火薬剤を使用するため、感電のおそれがある電気火災には適しません。","ひっかけ注意":"泡が火を覆う働きと、電気火災への適応性は別に判断します。","ここだけ覚える":"機械泡は電気火災に不適"},{"id":"tf-0014","教材":"ユーキャン","分野":"機械に関する基礎的知識","問題":"応力は、荷重をその荷重が作用する断面積で割って求める。","正解":"○","理由":"単位面積当たりに働く内力を応力といいます。","ひっかけ注意":"荷重に面積を掛けるのではありません。","ここだけ覚える":"応力＝荷重÷断面積"},{"id":"tf-0015","教材":"ユーキャン","分野":"機械に関する基礎的知識","問題":"引張荷重は物体を押し縮める方向に作用する荷重である。","正解":"×","理由":"引張荷重は物体を引き伸ばす方向に作用します。押し縮めるものは圧縮荷重です。","ひっかけ注意":"引張と圧縮を逆にしないようにします。","ここだけ覚える":"引張＝伸ばす、圧縮＝縮める"},{"id":"koron-tf-0001","教材":"公論出版","分野":"消防関係法令（共通）","問題":"小学校は、特定防火対象物に該当する。","正解":"×","理由":"小学校は非特定防火対象物です。","ひっかけ注意":"幼稚園は特定ですが、小学校は非特定です。","ここだけ覚える":"小学校＝非特定","出典":"公論出版 令和8年版 p.19-20（IMG_0746・IMG_0747）","公開前確認":true},{"id":"koron-tf-0002","教材":"公論出版","分野":"消防関係法令（共通）","問題":"百貨店は、特定防火対象物に該当する。","正解":"○","理由":"百貨店は特定防火対象物です。","ひっかけ注意":"物品販売店舗は特定として整理します。","ここだけ覚える":"百貨店＝特定","出典":"公論出版 令和8年版 p.19-20（IMG_0746・IMG_0747）","公開前確認":true},{"id":"koron-tf-0003","教材":"公論出版","分野":"消防関係法令（共通）","問題":"テレビスタジオは、特定防火対象物に該当する。","正解":"×","理由":"テレビスタジオは非特定防火対象物です。","ひっかけ注意":"映画館は特定ですが、映画・テレビスタジオは非特定です。","ここだけ覚える":"テレビスタジオ＝非特定","出典":"公論出版 令和8年版 p.19-20（IMG_0746・IMG_0747）","公開前確認":true},{"id":"koron-tf-0004","教材":"公論出版","分野":"消防関係法令（共通）","問題":"図書館と美術館は、いずれも非特定防火対象物である。","正解":"○","理由":"図書館と美術館はいずれも非特定防火対象物です。","ひっかけ注意":"人が集まる施設という印象だけで特定と判断しないようにします。","ここだけ覚える":"図書館・美術館＝非特定","出典":"公論出版 令和8年版 p.19-20（IMG_0746・IMG_0747）","公開前確認":true},{"id":"koron-tf-0005","教材":"公論出版","分野":"消防関係法令（共通）","問題":"蒸気浴場・熱気浴場などの公衆浴場は、特定防火対象物に該当する。","正解":"○","理由":"蒸気浴場・熱気浴場などは特定防火対象物です。","ひっかけ注意":"一般の公衆浴場との分類の違いに注意します。","ここだけ覚える":"蒸気浴場・熱気浴場＝特定","出典":"公論出版 令和8年版 p.19-20（IMG_0746・IMG_0747）","公開前確認":true},{"id":"koron-tf-0006","教材":"公論出版","分野":"消防関係法令（共通）","問題":"共同住宅は、特定防火対象物に該当する。","正解":"×","理由":"共同住宅は非特定防火対象物です。","ひっかけ注意":"宿泊施設の旅館は特定ですが、共同住宅は非特定です。","ここだけ覚える":"共同住宅＝非特定","出典":"公論出版 令和8年版 p.19-20（IMG_0746・IMG_0747）","公開前確認":true},{"id":"koron-tf-0007","教材":"公論出版","分野":"消防関係法令（第6類）","問題":"大型消火器は、指定可燃物の貯蔵・取扱場所の各部分から歩行距離30m以下となるよう設置する。","正解":"○","理由":"大型消火器の歩行距離は30m以下です。","ひっかけ注意":"通常消火器の20m以下と区別します。","ここだけ覚える":"大型消火器＝歩行距離30m以下","出典":"公論出版 令和8年版 p.124〜128（IMG_0855〜IMG_0859）","公開前確認":true},{"id":"koron-tf-0008","教材":"公論出版","分野":"消防関係法令（第6類）","問題":"指定可燃物を指定数量の300倍以上貯蔵すると、大型消火器の設置対象となる。","正解":"×","理由":"大型消火器の基準は指定数量の500倍以上です。","ひっかけ注意":"300倍ではなく500倍です。","ここだけ覚える":"大型消火器＝指定数量500倍以上","出典":"公論出版 令和8年版 p.124〜128（IMG_0855〜IMG_0859）","公開前確認":true},{"id":"koron-tf-0009","教材":"公論出版","分野":"消防関係法令（第6類）","問題":"大型消火器を設置した場合、同じ適応性を持つ消火器具の能力単位は3分の1まで減少できる。","正解":"×","理由":"大型消火器による減少は2分の1までです。","ひっかけ注意":"3分の1は別の消火設備による減少規定と混同しやすい数字です。","ここだけ覚える":"大型消火器による減少＝2分の1まで","出典":"公論出版 令和8年版 p.124〜128（IMG_0855〜IMG_0859）","公開前確認":true},{"id":"koron-tf-0010","教材":"公論出版","分野":"消防関係法令（第6類）","問題":"屋外消火栓設備は、大型消火器を省略できる消火設備に含まれる。","正解":"×","理由":"屋外消火栓設備は大型消火器の省略対象に含まれません。","ひっかけ注意":"屋内消火栓設備との違いに注意します。","ここだけ覚える":"屋外消火栓＝大型消火器省略の対象外","出典":"公論出版 令和8年版 p.124〜128（IMG_0855〜IMG_0859）","公開前確認":true}]};
